class UserError(Exception):
    """Błąd możliwy do naprawienia przez użytkownika; bez zrzutu stosu w UI."""


class Cancelled(UserError):
    pass


DEPENDENCY_MODULES = {'desktop':'PySide6.QtWidgets', 'oracle':'oracledb',
                      'firebird':'firebird.driver', 'h2':'jpype', 'secrets':'keyring'}
DEPENDENCY_NAMES = {'desktop':'interfejsu', 'oracle':'Oracle', 'firebird':'Firebirda',
                    'h2':'H2', 'secrets':'magazynu poświadczeń'}


def dependency_problem(profile, state, details=''):
    if profile not in DEPENDENCY_MODULES or state not in ('missing','broken','external'):
        raise UserError('Nieznany składnik przygotowania.')
    name=DEPENDENCY_NAMES[profile]
    title=('Obsługa '+name+' nie jest jeszcze przygotowana.' if state=='missing' else
           'Obsługa '+name+' wymaga naprawy.' if state=='broken' else
           'Obsługa '+name+' wymaga dodatkowego składnika.')
    message=('Przygotuj sterownik, aby połączyć się z bazą. Dane połączenia pozostaną zachowane.'
             if state=='missing' else 'Nie można załadować sterownika lub jednej z jego zależności. Przygotuj sprawdzone środowisko.'
             if state=='broken' else 'Wskaż wymagany składnik w ustawieniach połączeń. Pobranie pakietu Python go nie zastępuje.')
    return {'state':state,'profile':profile,'title':title,'message':message,'details':str(details)[:3500]}


class DependencyError(UserError):
    """Typed capability failure, also transported over the worker protocol."""
    def __init__(self, profile, state='missing', details=''):
        self.dependency=dependency_problem(profile,state,details)
        super().__init__(self.dependency['title']+' '+self.dependency['message']+
                         ('\n'+self.dependency['details'] if details else ''))


def dependency_status(profile, settings=None):
    """Cheap discovery in the running interpreter; the worker verifies the real import.

    A discoverable package is not proof of a working database connection.
    Native clients are checked when a particular connection requests them.
    """
    if profile not in DEPENDENCY_MODULES:
        return {'state':'ready','profile':profile,'title':'','message':'','details':''}
    module=DEPENDENCY_MODULES[profile]
    try:
        if importlib.util.find_spec(module) is None:
            return dependency_problem(profile,'missing', 'Brak pakietu '+module+' w interpreterze używanym przez Pivot Studio.')
    except ModuleNotFoundError as exc:
        state='missing' if exc.name and (module==exc.name or module.startswith(exc.name+'.')) else 'broken'
        return dependency_problem(profile,state,str(exc))
    except Exception as exc:
        return dependency_problem(profile,'broken',safe_error(exc))
    return {'state':'ready','profile':profile,'title':'Sterownik dostępny',
            'message':'Import i połączenie zostaną sprawdzone podczas otwierania źródła.','details':''}


def uid() -> str:
    return uuid.uuid4().hex


def dumps(value) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(',', ':'), allow_nan=False)


def digest(value) -> str:
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True,
                                     separators=(',', ':'), allow_nan=False).encode()).hexdigest()


def utcnow() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')


def private_dir(path: Path) -> Path:
    path.mkdir(parents=True, exist_ok=True)
    with contextlib.suppress(OSError):
        path.chmod(0o700)
    return path


def data_root() -> Path:
    if os.name == 'nt':
        base = Path(os.environ.get('LOCALAPPDATA', str(Path.home() / 'AppData/Local')))
    elif sys.platform == 'darwin':
        base = Path.home() / 'Library/Application Support'
    else:
        base = Path(os.environ.get('XDG_DATA_HOME', str(Path.home() / '.local/share')))
    return base / 'PivotStudio'


def atomic_bytes(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, name = tempfile.mkstemp(prefix='.' + path.name + '-', suffix='.tmp', dir=path.parent)
    try:
        with os.fdopen(fd, 'wb') as f:
            f.write(data); f.flush(); os.fsync(f.fileno())
        os.replace(name, path)
        with contextlib.suppress(OSError): path.chmod(0o600)
    finally:
        with contextlib.suppress(FileNotFoundError): os.unlink(name)


def file_digest(path: Path | str) -> str:
    path=Path(path)
    h = hashlib.sha256()
    with path.open('rb') as f:
        for block in iter(lambda: f.read(1024 * 1024), b''): h.update(block)
    return h.hexdigest()


def require_module(name: str, profile: str):
    try:
        return __import__(name, fromlist=['_'])
    except ModuleNotFoundError as exc:
        missing=exc.name and (name==exc.name or name.startswith(exc.name+'.'))
        raise DependencyError(profile,'missing' if missing else 'broken',safe_error(exc)) from exc
    except Exception as exc:
        raise DependencyError(profile,'broken',safe_error(exc)) from exc


def clean_text(value, limit=512) -> str:
    text = str(value or '').strip()
    if '\x00' in text or len(text) > limit:
        raise UserError('Tekst jest zbyt długi albo zawiera niedozwolony znak NUL.')
    return text


def qident(name: str) -> str:
    if not isinstance(name, str) or not name or '\x00' in name or len(name) > 512:
        raise UserError('Nieprawidłowy identyfikator bazy.')
    return '"' + name.replace('"', '""') + '"'


def safe_error(exc: Exception, password: str = '') -> str:
    msg = str(exc) or type(exc).__name__
    if password: msg = msg.replace(password, '[ukryte]')
    msg = re.sub(r'(?i)(password|pwd)\s*[=:]\s*[^\s;,]+', r'\1=[ukryte]', msg)
    return msg[:3500]


def pack(value):
    """Typowany transport IPC zachowujący dokładne liczby i wartości NULL."""
    if value is None: return None
    if isinstance(value, bool): return {'t': 'b', 'v': 'true' if value else 'false'}
    if isinstance(value, (int, Decimal)):
        if isinstance(value, Decimal) and not value.is_finite():
            raise UserError('Wynik zawiera NaN lub nieskończoność.')
        return {'t': 'n', 'v': str(value)}
    if isinstance(value, float):
        if not math.isfinite(value): raise UserError('Wynik zawiera NaN lub nieskończoność.')
        return {'t': 'n', 'v': repr(value)}
    if isinstance(value, (dt.datetime, dt.date, dt.time)):
        return {'t': 'd', 'v': value.isoformat()}
    if isinstance(value, (bytes, bytearray, memoryview)):
        return {'t': 's', 'v': f'[dane binarne: {len(value)} bajtów]'}
    # Lob/BlobReader są celowo nieodczytywane automatycznie.
    if hasattr(value, 'read'):
        return {'t': 's', 'v': '[LOB — treść nie jest pobierana do podglądu]'}
    text = str(value)
    if len(text) > MAX_CELL_TEXT:
        raise UserError(f'Wartość przekracza {MAX_CELL_TEXT} znaków. Wyłącz kolumnę LOB/tekstową lub skróć ją w SQL.')
    return {'t': 's', 'v': text}


def unpack(cell):
    if cell is None: return None
    if cell['t'] == 'n': return Decimal(cell['v'])
    if cell['t'] == 'b': return cell['v'] == 'true'
    return cell['v']


def display_cell(cell, fmt='auto') -> str:
    if cell is None: return '∅'
    if cell['t'] == 'b': return 'Tak' if cell['v'] == 'true' else 'Nie'
    if cell['t'] != 'n': return cell['v']
    with localcontext() as c:
        c.prec = 100
        number = Decimal(cell['v'])
        if fmt == 'percent': number *= 100
        places = 2 if fmt in ('money', 'percent') else (0 if fmt == 'integer' else 6)
        if number.adjusted() > 70: return str(number)
        text = format(number.quantize(Decimal(1).scaleb(-places)), 'f')
        if fmt == 'auto' and '.' in text: text = text.rstrip('0').rstrip('.')
    left, sep, right = text.partition('.')
    left = re.sub(r'(?<=\d)(?=(\d{3})+$)', '\u202f', left)
    return left + (',' + right if sep else '') + ('%' if fmt == 'percent' else '')


# ======================== 1. MODEL I WALIDACJA ===============================
SOURCE_KEYS = {
    'xlsx': {'path', 'origin', 'owned'},
    'sqlite': {'path', 'owned'},
    'h2': {'mode', 'path', 'host', 'port', 'database', 'user'},
    'firebird': {'host', 'port', 'database', 'user', 'charset', 'role'},
    'oracle': {'host', 'port', 'service', 'sid', 'user', 'mode', 'schema'},
}


def validate_source(value: dict) -> dict:
    if not isinstance(value, dict): raise UserError('Nieprawidłowa definicja źródła.')
    kind = value.get('kind')
    if kind not in SOURCE_KEYS: raise UserError('Nieobsługiwany typ źródła.')
    raw = value.get('options', {})
    if not isinstance(raw, dict) or set(raw) - SOURCE_KEYS[kind]:
        raise UserError('Źródło zawiera nieobsługiwane opcje lub sekret.')
    options = {}
    for k, v in raw.items():
        if k == 'port':
            try: v = int(v)
            except (ValueError, TypeError): raise UserError('Port musi być liczbą.')
            if not 1 <= v <= 65535: raise UserError('Port poza zakresem 1–65535.')
        elif k == 'owned': v = bool(v)
        else: v = clean_text(v, 2048)
        options[k] = v
    for k in ('host', 'database', 'path'):
        if kind == 'h2' and any(x in str(options.get(k, '')) for x in (';', '\n', '\r', '?')):
            raise UserError('H2: znaki ; ? i nowe linie są niedozwolone. Parametry INIT i własne URL JDBC nie są obsługiwane.')
    if kind == 'h2' and options.get('mode', 'file') not in ('file', 'tcp', 'ssl'):
        raise UserError('Nieprawidłowy tryb H2.')
    if kind == 'oracle' and options.get('mode', 'thin') not in ('thin', 'thick'):
        raise UserError('Nieprawidłowy tryb Oracle.')
    result = {'id': clean_text(value.get('id') or uid(), 64), 'kind': kind,
              'name': clean_text(value.get('name') or KIND_NAMES[kind], 100), 'options': options}
    if kind == 'xlsx': result['workbook'] = validate_workbook(value.get('workbook'))
    return result


def validate_dataset(raw: dict) -> dict:
    if not isinstance(raw, dict): raise UserError('Nieprawidłowy zbiór danych.')
    result = {k: clean_text(raw.get(k, ''), 50000 if k == 'sql' else 512)
              for k in ('source_id', 'schema', 'table', 'sql')}
    if not result['source_id']: raise UserError('Wybierz źródło danych.')
    if bool(result['table']) == bool(result['sql']):
        raise UserError('Wybierz tabelę albo zapytanie SQL, nie oba naraz.')
    if result['sql']: result['sql'] = validate_select(result['sql'])
    if raw.get('dataset_id') or raw.get('snapshot_id'):
        result['dataset_id'] = workbook_id(raw.get('dataset_id'))
        result['snapshot_id'] = workbook_id(raw.get('snapshot_id'))
    return result


def validate_analysis(raw: dict) -> dict:
    if not isinstance(raw, dict): raise UserError('Nieprawidłowa analiza.')
    a = {'id': clean_text(raw.get('id') or uid(), 64),
         'name': clean_text(raw.get('name') or 'Nowa analiza', 100),
         'dataset': validate_dataset(raw.get('dataset', {})),
         'rows': [], 'columns': [], 'measures': [], 'filters': [], 'calculations': [],
         'totals': bool(raw.get('totals', True)), 'subtotals': bool(raw.get('subtotals', False))}
    for axis, limit in (('rows', 3), ('columns', 2)):
        values = raw.get(axis, [])
        if not isinstance(values, list) or len(values) > limit:
            raise UserError(f'Maksymalnie {limit} pola w obszarze {axis}.')
        for d in values:
            grain = d.get('grain', 'raw')
            if grain not in ('raw', 'year', 'month', 'day'): raise UserError('Nieobsługiwane grupowanie dat.')
            a[axis].append({'field': clean_text(d.get('field'), 512), 'grain': grain})
    dims = a['rows'] + a['columns']
    if len({(d['field'], d['grain']) for d in dims}) != len(dims):
        raise UserError('To samo pole i grupowanie nie może wystąpić jednocześnie na obu osiach.')
    ms = raw.get('measures', [])
    if not isinstance(ms, list) or len(ms) > 12: raise UserError('Maksymalnie 12 miar.')
    for m in ms:
        agg = m.get('agg', 'sum')
        if agg not in AGG_NAMES: raise UserError('Nieobsługiwana agregacja.')
        fmt = m.get('format', 'auto')
        if fmt not in ('auto', 'money', 'integer', 'percent'): raise UserError('Nieobsługiwany format.')
        a['measures'].append({'id': clean_text(m.get('id') or uid(), 64),
                              'field': clean_text(m.get('field', ''), 512), 'agg': agg,
                              'label': clean_text(m.get('label', ''), 100), 'format': fmt,
                              'numerator': clean_text(m.get('numerator', ''), 64),
                              'denominator': clean_text(m.get('denominator', ''), 64)})
    if len({m['id'] for m in a['measures']}) != len(a['measures']): raise UserError('Powtórzone identyfikatory miar.')
    base_ids = {m['id'] for m in a['measures'] if m['agg'] != 'ratio'}
    for m in a['measures']:
        if m['agg'] == 'ratio' and (m['numerator'] not in base_ids or m['denominator'] not in base_ids):
            raise UserError('Iloraz musi odnosić się do dwóch istniejących miar bazowych.')
    fs = raw.get('filters', [])
    if not isinstance(fs, list) or len(fs) > 30: raise UserError('Maksymalnie 30 filtrów.')
    for f in fs:
        op = f.get('op', 'eq')
        if op not in ('eq','ne','gt','ge','lt','le','contains','starts','ends','in','between','isnull','notnull'):
            raise UserError('Nieobsługiwany operator filtra.')
        v = f.get('value', '')
        if isinstance(v, list):
            if len(v) > 300: raise UserError('Maksymalnie 300 wartości w filtrze IN.')
            v = [clean_text(x, 2000) for x in v]
        else: v = clean_text(v, 2000)
        grain = f.get('grain', 'raw')
        if grain not in ('raw','year','month','day'): raise UserError('Nieprawidłowy filtr daty.')
        a['filters'].append({'field': clean_text(f.get('field'),512),'op':op,'value':v,'grain':grain})
    cs = raw.get('calculations', [])
    if not isinstance(cs, list) or len(cs) > 12: raise UserError('Maksymalnie 12 pól obliczeniowych.')
    for c in cs:
        name = clean_text(c.get('name'),100)
        if not name: raise UserError('Pole obliczeniowe musi mieć nazwę.')
        a['calculations'].append({'name':name, 'expr':clean_text(c.get('expr'),2000)})
    if len({c['name'] for c in a['calculations']}) != len(a['calculations']):
        raise UserError('Powtórzone nazwy pól obliczeniowych.')
    return a


def new_project() -> dict:
    return {'version': PROJECT_VERSION, 'name': 'Bez tytułu', 'sources': [], 'analyses': [], 'active': '', 'workpads': [], 'active_workpad': '', 'join_views': []}


def validate_project(raw: dict) -> dict:
    if not isinstance(raw, dict) or raw.get('version') not in (1, 2, 3, PROJECT_VERSION):
        raise UserError('Nieobsługiwana wersja projektu. Nie wykonano migracji ani zmian w pliku.')
    if len(raw.get('sources', [])) > 100 or len(raw.get('analyses', [])) > 200:
        raise UserError('Projekt przekracza limit źródeł lub analiz.')
    if not isinstance(raw.get('join_views',[]),list) or len(raw.get('join_views',[]))>100:raise UserError('Nieprawidłowa lista zapisanych połączeń tabel.')
    p = {'version':PROJECT_VERSION, 'name':clean_text(raw.get('name','Projekt'),100),
         'sources':[validate_source(s) for s in raw.get('sources',[])],
         'analyses':[validate_analysis(a) for a in raw.get('analyses',[])],
         'active':clean_text(raw.get('active',''),64),
         'workpads':[sheet_validate_book(b) for b in raw.get('workpads',[])],
         'active_workpad':clean_text(raw.get('active_workpad',''),64),
         'join_views':[database_saved_join(v) for v in raw.get('join_views',[])]}
    if len(p['workpads'])>12 or len({b['id'] for b in p['workpads']})!=len(p['workpads']):
        raise UserError('Projekt może zawierać do 12 różnych skoroszytów roboczych.')
    if len(dumps(p).encode('utf-8'))>SHEET_MAX_BYTES:raise UserError('Definicja projektu z arkuszami przekracza 32 MB.')
    sids = {s['id'] for s in p['sources']}
    if len(sids) != len(p['sources']): raise UserError('Powtórzone identyfikatory źródeł.')
    aids = {a['id'] for a in p['analyses']}
    if len(aids) != len(p['analyses']): raise UserError('Powtórzone identyfikatory analiz.')
    if any(a['dataset']['source_id'] not in sids for a in p['analyses']):
        raise UserError('Analiza odwołuje się do nieistniejącego źródła.')
    for a in p['analyses']:
        source=next(s for s in p['sources'] if s['id']==a['dataset']['source_id'])
        if source['kind']=='xlsx': workbook_version(source,a['dataset'])
    joins=p['join_views']
    if len(joins)>100 or len({v['id'] for v in joins})!=len(joins):raise UserError('Projekt może zawierać do 100 różnych zapisanych połączeń tabel.')
    by_source={s['id']:s for s in p['sources']}
    for view in joins:
        plan=view['plan'];source=by_source.get(plan['source_id'])
        if source is None or source['kind']!=plan['backend']:raise UserError('Zapisane połączenie nie pasuje do źródła w projekcie.')
    if p['active'] not in aids: p['active'] = next(iter(aids), '')
    return p


