def export_result(result_path,destination,fmt,cancelled=None):
    meta=ResultStore.metadata(result_path); destination=Path(destination).resolve()
    if fmt not in ('csv','xlsx'): raise UserError('Nieobsługiwany format eksportu.')
    destination=destination.with_suffix('.'+fmt)
    fd,temp=tempfile.mkstemp(prefix='.'+destination.name+'-',suffix='.tmp',dir=destination.parent); os.close(fd)
    headers=[(c.get('group','')+' / ' if c.get('group') else '')+c['label'] for c in meta['columns']]
    try:
        if fmt=='csv':
            with open(temp,'w',encoding='utf-8-sig',newline='') as f:
                writer=csv.writer(f,delimiter=';'); writer.writerow([csv_safe(pack(h)) for h in headers])
                for cells,_ in ResultStore.iter_rows(result_path):
                    if cancelled and cancelled.is_set(): raise Cancelled('Eksport anulowany.')
                    writer.writerow([csv_safe(c) for c in cells])
            # Scope metadata travels with CSV as an explicit sidecar, never mislabeled as full data.
            sidecar=destination.with_suffix('.csv.meta.json')
            atomic_bytes(sidecar,json.dumps(meta,ensure_ascii=False,indent=2).encode('utf-8'))
        else:
            with zipfile.ZipFile(temp,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=6) as z:
                z.writestr('[Content_Types].xml','''<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>''')
                z.writestr('_rels/.rels','''<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>''')
                z.writestr('xl/workbook.xml','''<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Wynik" sheetId="1" r:id="rId1"/><sheet name="Metadane" sheetId="2" r:id="rId2"/></sheets></workbook>''')
                z.writestr('xl/_rels/workbook.xml.rels','''<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>''')
                z.writestr('xl/styles.xml',XLSX_STYLES)
                with z.open('xl/worksheets/sheet1.xml','w') as f:
                    def write(s): f.write(s.encode('utf-8'))
                    frozen=sum(bool(c.get('dimension')) for c in meta['columns'])
                    write('<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="'+XNS['s']+'"><dimension ref="A1:'+excel_column(len(meta['columns'])-1)+str(meta['row_count']+1)+'"/><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" xSplit="'+str(frozen)+'" topLeftCell="'+excel_column(frozen)+'2" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="20"/><cols>')
                    for i,col in enumerate(meta['columns'],1):
                        width=min(40,max(18,len(col['label'])+2))
                        write(f'<col min="{i}" max="{i}" width="{width}" customWidth="1"/>')
                    write('</cols><sheetData><row r="1" ht="36" customHeight="1">')
                    for i,h in enumerate(headers): write(xlsx_cell(excel_column(i)+'1',pack(h),1))
                    write('</row>')
                    for rownum,(cells,total) in enumerate(ResultStore.iter_rows(result_path),2):
                        if cancelled and cancelled.is_set(): raise Cancelled('Eksport anulowany.')
                        write(f'<row r="{rownum}">')
                        for i,(cell,col) in enumerate(zip(cells,meta['columns'])):
                            st=6 if total else 0
                            if cell and cell['t']=='n':
                                st={'auto':2,'money':3,'integer':4,'percent':5}[col['format']]+(5 if total else 0)
                            write(xlsx_cell(excel_column(i)+str(rownum),cell,st))
                        write('</row>')
                    write('</sheetData></worksheet>')
                info=[('Analiza',meta['analysis']['name']),('Utworzono (UTC)',meta['created']),
                      ('Źródło',meta['source_name']+' / '+meta['backend']),('Zakres',meta['scope_note']),
                      ('Wiersze wyniku',str(meta['row_count'])),('Rewizja',meta['fingerprint']),
                      ('Format','Statyczny wynik — nie natywna tabela przestawna Excela. Liczby >15 cyfr znaczących zapisano jako tekst.'),
                      ('Filtry',dumps(meta['analysis']['filters'])),('Ostrzeżenia','\n'.join(meta['warnings']))]
                for i,q in enumerate(meta['queries'],1):
                    info.append((f'SQL {i}',q['sql'])); info.append((f'Parametry {i}',dumps(q['parameters'])))
                xml='<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="'+XNS['s']+'"><dimension ref="A1:B'+str(len(info))+'"/><cols><col min="1" max="1" width="26" customWidth="1"/><col min="2" max="2" width="90" customWidth="1"/></cols><sheetData>'
                for i,(k,v) in enumerate(info,1):
                    xml+=f'<row r="{i}" ht="44" customHeight="1">'+xlsx_cell('A'+str(i),pack(k),1)+xlsx_cell('B'+str(i),pack(v),11)+'</row>'
                z.writestr('xl/worksheets/sheet2.xml',xml+'</sheetData></worksheet>')
        with open(temp,'r+b') as f: os.fsync(f.fileno())
        os.replace(temp,destination)
        return {'path':str(destination),'rows':meta['row_count'],'metadata_path':str(destination.with_suffix('.csv.meta.json')) if fmt=='csv' else ''}
    finally:
        with contextlib.suppress(FileNotFoundError): os.unlink(temp)

# ================= Database explorer: metadata, not an implicit analysis =====
DATABASE_CATALOG_FORMAT = 1
DATABASE_MAX_OBJECTS = 20000
DATABASE_MAX_ITEMS = 150000
DATABASE_MAX_METADATA_BYTES = 24 * 1024 * 1024


class DatabaseCatalogLimit(UserError):
    """A working connection whose metadata needs a narrower explicit scope."""
    def __init__(self,message,scope):
        super().__init__(message);self.catalog_scope=clone(scope)


DATABASE_PAGE_SIZE = 200
DATABASE_KINDS = {'table':'Tabele', 'view':'Widoki', 'materialized view':'Widoki materializowane',
                  'index':'Indeksy', 'trigger':'Wyzwalacze', 'sequence':'Sekwencje',
                  'procedure':'Procedury', 'function':'Funkcje', 'package':'Pakiety',
                  'domain':'Domeny', 'synonym':'Synonimy', 'type':'Typy'}
DATABASE_RELATIONS = frozenset(('table','view','materialized view'))


def database_object_id(schema, kind, name):
    """Names are case-sensitive metadata, never parsed SQL or positional IDs."""
    return digest([str(schema), str(kind).lower(), str(name)])[:32]


def database_label(obj):
    return (obj.get('schema','') + '.' if obj.get('schema') else '') + obj['name']


def database_metadata_text(value, limit=256000):
    if value is None: return ''
    if hasattr(value, 'read'):
        # Read only catalogue text, never application LOB contents.
        try: value = value.read(offset=1, amount=limit + 1)
        except TypeError: value = value.read(limit + 1)
    if isinstance(value, bytes): value = value.decode('utf-8', 'replace')
    text = str(value)
    if len(text) > limit: raise UserError('Definicja obiektu przekracza limit odczytu metadanych.')
    return text


def sqlite_metadata_authorizer(action, a, b, db, trigger):
    if action == sqlite3.SQLITE_PRAGMA:
        return sqlite3.SQLITE_OK if str(a).lower() in {
            'table_xinfo','table_list','index_list','index_xinfo','foreign_key_list',
            'schema_version','database_list'} else sqlite3.SQLITE_DENY
    return sqlite_authorizer(action, a, b, db, trigger)


class DatabaseInspector:
    """One owned read connection; no user table SELECTs while exploring schema.

    Snapshot publication is all-or-explicitly-partial. Per-section failures remain
    visible. Limits fail rather than silently claiming a truncated catalogue is full.
    Object and relation names come from the database, never heuristic name matching.
    """
    def __init__(self, adapter, progress=None, schema=None):
        self.adapter=adapter; self.progress=progress or (lambda text:None)
        self.objects={};self.warnings=[];self.scopes=[];self.relations=[];self.section_state={}
        self.schema=(adapter.options.get('schema','') if schema is None else schema) if adapter.kind=='oracle' else ''
        if not isinstance(self.schema,str) or len(self.schema)>512 or any(ord(c)<32 for c in self.schema):
            raise UserError('Nieprawidłowy schemat odczytu katalogu.')
        self._oracle_scope=None
    def add(self, kind, schema, name, **extra):
        kind=str(kind).lower();schema=str(schema or '');name=str(name)
        key=database_object_id(schema,kind,name)
        if key not in self.objects:
            if len(self.objects)>=DATABASE_MAX_OBJECTS:
                message=f'Katalog przekracza {DATABASE_MAX_OBJECTS:,} obiektów. Nie oznaczono go jako kompletny.'
                if self._oracle_scope is not None:raise DatabaseCatalogLimit(message+' Wybierz węższy zakres odczytu.',self._oracle_scope)
                raise UserError(message)
            self.objects[key]={'id':key,'kind':kind,'schema':schema,'name':name,'parent':'',
                'system':False,'columns':[],'keys':[],'indexes':[],'definition':'',
                'definition_kind':'unavailable','properties':{},'problems':[]}
        self.objects[key].update(extra)
        return self.objects[key]
    def relation(self, schema, name):
        for kind in DATABASE_RELATIONS:
            obj=self.objects.get(database_object_id(schema,kind,name))
            if obj:return obj
        if self.adapter.kind=='sqlite':
            # SQLite folds ASCII identifier letters, but not arbitrary Unicode.
            lower=lambda value:str(value).translate(str.maketrans('ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'))
            return next((o for o in self.objects.values() if o['kind'] in DATABASE_RELATIONS and
                         lower(o['schema'])==lower(schema) and lower(o['name'])==lower(name)),None)
        return None
    def section(self, label, function):
        self.adapter.check_cancel();self.progress('Struktura · '+label)
        try:
            value=function();self.section_state[label]='complete';return value
        except (Cancelled,DatabaseCatalogLimit):raise
        except Exception as exc:
            self.adapter.check_cancel()
            message=label+': '+safe_error(exc,self.adapter.password)
            self.warnings.append(message);self.section_state[label]='partial';return None
    def rows(self, sql, params=()):
        return self.adapter.fetch(sql,params,limit=DATABASE_MAX_ITEMS)
    def pragma(self, name, value=None):
        if name not in ('table_xinfo','table_list','index_list','index_xinfo','foreign_key_list','schema_version'):
            raise UserError('Niedozwolony odczyt metadanych SQLite.')
        sql='PRAGMA main.'+name
        if value is not None:sql+='('+"'"+str(value).replace("'","''")+"'"+')'
        return self.rows(sql)
    def read(self):
        start=time.monotonic();a=self.adapter
        if a.kind not in ('sqlite','h2','firebird','oracle'):raise UserError('To źródło nie jest połączeniem z bazą.')
        self.progress('Odczytuję katalog obiektów; nie pobieram zawartości tabel.')
        getattr(self,'read_'+a.kind)()
        a.check_cancel()
        objects=list(self.objects.values())
        objects.sort(key=lambda o:(o['schema'].casefold(),o['kind'],o['name'].casefold(),o['name']))
        for obj in objects:
            obj['columns'].sort(key=lambda c:c['position'])
            for key in obj['keys']:
                if key['kind']=='PRIMARY KEY':
                    order={name:i+1 for i,name in enumerate(key.get('columns',[]))}
                    for col in obj['columns']:
                        if col['name'] in order:col['pk_position']=order[col['name']]
                elif key['kind']=='FOREIGN KEY':
                    target=self.relation(key.get('target_schema',''),key.get('target_table',''))
                    targets=list(key.get('target_columns',[]))
                    if target and (not targets or any(n is None for n in targets)):
                        pk=next((k['columns'] for k in target['keys'] if k['kind']=='PRIMARY KEY'),[])
                        if len(pk)==len(key.get('columns',[])):targets=list(pk)
                    if target:
                        normalize=(lambda value:str(value).translate(str.maketrans('ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'))) if a.kind=='sqlite' else str
                        named={normalize(c['name']):c['name'] for c in target['columns']}
                        targets=[named.get(normalize(c),c) if c is not None else None for c in targets]
                        resolved=bool(targets and len(targets)==len(key.get('columns',[])) and
                                      all(c is not None and normalize(c) in named for c in targets))
                    else:resolved=False
                    source_columns=list(key.get('columns',[]))
                    if a.kind=='sqlite':
                        fold=lambda value:str(value).translate(str.maketrans('ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'))
                        source_names={fold(c['name']):c['name'] for c in obj['columns']}
                        source_columns=[source_names.get(fold(c),c) for c in source_columns]
                        resolved=resolved and all(fold(c) in source_names for c in source_columns)
                    edge={'id':digest([obj['id'],key['name'],source_columns])[:32],
                        'source':obj['id'],'target':target['id'] if target else '', 'name':key['name'],
                        'source_columns':source_columns,'target_columns':targets,
                        'target_schema':key.get('target_schema',''),'target_table':key.get('target_table',''),
                        'on_update':key.get('on_update',''),'on_delete':key.get('on_delete',''),
                        'declared':True,'resolved':resolved,'integrity_checked':False,
                        'enforced':key.get('enforced',None)}
                    self.relations.append(edge)
        counts=dict(collections.Counter(o['kind'] for o in objects))
        out={'version':DATABASE_CATALOG_FORMAT,'source_id':a.source['id'],'backend':a.kind,
             'scope':self.scopes,'objects':objects,'relations':self.relations,'counts':counts,
             'warnings':self.warnings,'sections':self.section_state,'complete':not self.warnings,
             'metadata_only':True,'integrity_checked':False,'read_at':utcnow(),'elapsed':time.monotonic()-start}
        if self._oracle_scope is not None:out['oracle_scope']=clone(self._oracle_scope)
        out['fingerprint']=digest({'objects':objects,'relations':self.relations,'scope':self.scopes})
        if len(dumps(out).encode('utf-8'))>DATABASE_MAX_METADATA_BYTES:
            message='Metadane przekraczają 24 MB. Katalog nie został uznany za kompletny.'
            if self._oracle_scope is not None:raise DatabaseCatalogLimit(message+' Wybierz węższy zakres odczytu.',self._oracle_scope)
            raise UserError(message)
        return out
    def read_sqlite(self):
        a=self.adapter;a.conn.set_authorizer(sqlite_metadata_authorizer)
        self.scopes=['SQLite · main · obiekty zapisane w otwartym pliku. Bez baz ATTACH i obiektów tymczasowych innych sesji.']
        try:
            rows=self.rows("SELECT type,name,tbl_name,sql FROM main.sqlite_schema ORDER BY type,name")
            for typ,name,parent,sql in rows:
                self.add(typ,'main',name,parent=parent if parent!=name else '',system=name.startswith('sqlite_'),
                    definition=database_metadata_text(sql),definition_kind='original' if sql else 'implicit',
                    properties={'Silnik':'SQLite '+sqlite3.sqlite_version})
            # Meta-only flags available on SQLite 3.37+; absence is not an empty schema.
            try:
                for schema,name,typ,ncol,wr,strict,*_ in self.pragma('table_list'):
                    obj=self.relation(schema,name)
                    if obj:obj['properties'].update({'Rodzaj':typ,'WITHOUT ROWID':bool(wr),'STRICT':bool(strict)})
            except Exception as exc:
                a.check_cancel();self.warnings.append('Flagi tabel SQLite: '+safe_error(exc))
            relations=[o for o in self.objects.values() if o['kind'] in DATABASE_RELATIONS]
            for i,obj in enumerate(relations):
                a.check_cancel();self.progress(f'Struktura · {i+1}/{len(relations)} · {obj["name"]}')
                try:
                    columns=self.pragma('table_xinfo',obj['name'])
                    obj['columns']=[{'name':r[1],'type':r[2] or '', 'position':int(r[0])+1,
                        'nullable':not bool(r[3]), 'default':r[4], 'pk_position':int(r[5]),
                        'hidden':int(r[6])==1, 'generated':int(r[6]) in (2,3)} for r in columns]
                    pk=[c['name'] for c in sorted(obj['columns'],key=lambda c:c['pk_position']) if c['pk_position']]
                    if pk:obj['keys'].append({'name':'PRIMARY KEY','kind':'PRIMARY KEY','columns':pk})
                    # A rowid alias, STRICT and WITHOUT ROWID PK are not nullable.
                    # Ordinary composite/text rowid-table PK may still permit NULL.
                    if obj['kind']=='table':
                        indexes=self.pragma('index_list',obj['name'])
                        alias=(len(pk)==1 and next(c['type'].upper() for c in obj['columns'] if c['name']==pk[0])=='INTEGER'
                               and not any(r[3]=='pk' for r in indexes) and obj['properties'].get('Rodzaj')!='virtual') if pk else False
                        for col in obj['columns']:
                            if col['pk_position'] and (alias or obj['properties'].get('STRICT') or obj['properties'].get('WITHOUT ROWID')):col['nullable']=False
                        for seq,name,unique,origin,partial,*_ in indexes:
                            ix=self.objects.get(database_object_id('main','index',name)) or self.add('index','main',name,parent=obj['name'],system=name.startswith('sqlite_'),definition_kind='implicit')
                            parts=[]
                            for order,cid,cname,desc,coll,key,*_ in self.pragma('index_xinfo',name):
                                parts.append({'position':order+1,'name':cname,'cid':cid,'direction':'DESC' if desc else 'ASC',
                                              'collation':coll,'key':bool(key),'expression':cid==-2})
                            ix['properties'].update({'Unikalny':bool(unique),'Pochodzenie':origin,'Częściowy':bool(partial)})
                            ix['index_columns']=parts;obj['indexes'].append(ix['id'])
                            names=[p['name'] if p['name'] is not None else ('<wyrażenie>' if p['expression'] else '<rowid>') for p in parts if p['key']]
                            if origin=='u':obj['keys'].append({'name':name,'kind':'UNIQUE','columns':names})
                        grouped=collections.defaultdict(list)
                        for r in self.pragma('foreign_key_list',obj['name']):grouped[r[0]].append(r)
                        for key,rows in grouped.items():
                            rows.sort(key=lambda x:x[1]);first=rows[0]
                            obj['keys'].append({'name':'FK '+str(key+1),'kind':'FOREIGN KEY',
                                'columns':[r[3] for r in rows],'target_schema':'main','target_table':first[2],
                                'target_columns':[r[4] for r in rows],'on_update':first[5],'on_delete':first[6],
                                'enforced':None})
                    obj['properties']['Ograniczenia CHECK']='Pełne wyrażenia są w oryginalnej definicji SQL; nie są zgadywane z nazw.'
                except Cancelled:raise
                except Exception as exc:
                    a.check_cancel();msg=safe_error(exc);obj['problems'].append(msg);self.warnings.append(database_label(obj)+': '+msg)
            self.section_state['sqlite_schema']='complete';self.section_state['kolumny i klucze']='partial' if self.warnings else 'complete'
        finally:a.conn.set_authorizer(sqlite_authorizer)
    def read_h2(self):
        self.scopes=['H2 2.x · katalog INFORMATION_SCHEMA dostępny połączeniu; obiekty systemowe oznaczone osobno.']
        # Bulk reads avoid one network round trip per column/table.
        for schema,name,typ,remarks in self.rows('SELECT TABLE_SCHEMA,TABLE_NAME,TABLE_TYPE,REMARKS FROM INFORMATION_SCHEMA.TABLES'):
            self.add('view' if typ=='VIEW' else 'table',schema,name,system=schema=='INFORMATION_SCHEMA',properties={'Rodzaj':typ,'Opis':remarks or ''})
        def columns():
            for sc,tn,n,typ,pos,nullable,default,generated in self.rows('SELECT TABLE_SCHEMA,TABLE_NAME,COLUMN_NAME,DATA_TYPE,ORDINAL_POSITION,IS_NULLABLE,COLUMN_DEFAULT,IS_GENERATED FROM INFORMATION_SCHEMA.COLUMNS'):
                obj=self.relation(sc,tn)
                if obj:obj['columns'].append({'name':n,'type':typ,'position':int(pos),'nullable':nullable=='YES',
                    'default':database_metadata_text(default),'pk_position':0,'hidden':False,'generated':generated=='ALWAYS'})
        self.section('Kolumny',columns)
        def constraints():
            usage=collections.defaultdict(list)
            for sc,n,c,pos,refpos in self.rows('SELECT CONSTRAINT_SCHEMA,CONSTRAINT_NAME,COLUMN_NAME,ORDINAL_POSITION,POSITION_IN_UNIQUE_CONSTRAINT FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE ORDER BY ORDINAL_POSITION'):
                usage[(sc,n)].append((c,int(pos),int(refpos) if refpos is not None else None))
            checks={(sc,n):database_metadata_text(text) for sc,n,text in self.rows('SELECT CONSTRAINT_SCHEMA,CONSTRAINT_NAME,CHECK_CLAUSE FROM INFORMATION_SCHEMA.CHECK_CONSTRAINTS')}
            refs={(sc,n):(usc,un,ur,dr) for sc,n,usc,un,ur,dr in self.rows('SELECT CONSTRAINT_SCHEMA,CONSTRAINT_NAME,UNIQUE_CONSTRAINT_SCHEMA,UNIQUE_CONSTRAINT_NAME,UPDATE_RULE,DELETE_RULE FROM INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS')}
            records=self.rows('SELECT CONSTRAINT_SCHEMA,CONSTRAINT_NAME,CONSTRAINT_TYPE,TABLE_SCHEMA,TABLE_NAME FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS')
            lookup={(r[0],r[1]):r for r in records}
            for sc,n,kind,ts,tn in records:
                obj=self.relation(ts,tn)
                if not obj:continue
                key={'name':n,'kind':'FOREIGN KEY' if kind in ('REFERENTIAL','FOREIGN KEY') else kind,'columns':[x[0] for x in usage[(sc,n)]]}
                if kind=='CHECK':key['expression']=checks.get((sc,n),'')
                if (sc,n) in refs:
                    rsc,rn,ur,dr=refs[(sc,n)];target=lookup.get((rsc,rn));ru={x[1]:x[0] for x in usage[(rsc,rn)]}
                    key.update(target_schema=target[3] if target else rsc,target_table=target[4] if target else '',
                        target_columns=[ru.get(x[2]) for x in usage[(sc,n)]],on_update=ur,on_delete=dr)
                obj['keys'].append(key)
        self.section('Klucze i ograniczenia',constraints)
        def indexes():
            for sc,n,ts,tn,typ in self.rows('SELECT INDEX_SCHEMA,INDEX_NAME,TABLE_SCHEMA,TABLE_NAME,INDEX_TYPE_NAME FROM INFORMATION_SCHEMA.INDEXES'):
                obj=self.add('index',sc,n,parent=tn,system=ts=='INFORMATION_SCHEMA',properties={'Rodzaj':typ},index_columns=[])
                table=self.relation(ts,tn)
                if table:table['indexes'].append(obj['id'])
            for sc,n,c,pos,direction in self.rows('SELECT INDEX_SCHEMA,INDEX_NAME,COLUMN_NAME,ORDINAL_POSITION,ORDERING_SPECIFICATION FROM INFORMATION_SCHEMA.INDEX_COLUMNS ORDER BY ORDINAL_POSITION'):
                obj=self.objects.get(database_object_id(sc,'index',n))
                if obj:obj['index_columns'].append({'name':c,'position':int(pos),'direction':direction,'key':True})
        self.section('Indeksy',indexes)
        def view_defs():
            for sc,n,sql in self.rows('SELECT TABLE_SCHEMA,TABLE_NAME,VIEW_DEFINITION FROM INFORMATION_SCHEMA.VIEWS'):
                obj=self.relation(sc,n)
                if obj:obj.update(definition=database_metadata_text(sql),definition_kind='view query' if sql else 'unavailable')
        def triggers():
            for sc,n,tn,event,timing,java in self.rows('SELECT TRIGGER_SCHEMA,TRIGGER_NAME,EVENT_OBJECT_TABLE,EVENT_MANIPULATION,ACTION_TIMING,JAVA_CLASS FROM INFORMATION_SCHEMA.TRIGGERS'):
                obj=self.add('trigger',sc,n,parent=tn,system=sc=='INFORMATION_SCHEMA')
                events=obj['properties'].setdefault('Zdarzenia',[])
                if event not in events:events.append(event)
                obj['properties'].update({'Moment':timing,'Klasa Java':java or ''})
        def sequences():
            for sc,n,typ,start,inc in self.rows('SELECT SEQUENCE_SCHEMA,SEQUENCE_NAME,DATA_TYPE,START_VALUE,INCREMENT FROM INFORMATION_SCHEMA.SEQUENCES'):
                self.add('sequence',sc,n,system=sc=='INFORMATION_SCHEMA',properties={'Typ':typ,'Początek':str(start),'Krok':str(inc)})
        def routines():
            for sc,n,kind,sql,external in self.rows('SELECT ROUTINE_SCHEMA,SPECIFIC_NAME,ROUTINE_TYPE,ROUTINE_DEFINITION,EXTERNAL_NAME FROM INFORMATION_SCHEMA.ROUTINES'):
                self.add(str(kind).lower(),sc,n,system=sc=='INFORMATION_SCHEMA',definition=database_metadata_text(sql),definition_kind='source' if sql else 'unavailable',properties={'Implementacja':external or ''})
        def domains():
            for sc,n,typ in self.rows('SELECT DOMAIN_SCHEMA,DOMAIN_NAME,DATA_TYPE FROM INFORMATION_SCHEMA.DOMAINS'):
                self.add('domain',sc,n,system=sc=='INFORMATION_SCHEMA',properties={'Typ':typ})
        def synonyms():
            for sc,n,ts,tn in self.rows('SELECT SYNONYM_SCHEMA,SYNONYM_NAME,SYNONYM_FOR_SCHEMA,SYNONYM_FOR FROM INFORMATION_SCHEMA.SYNONYMS'):
                self.add('synonym',sc,n,system=sc=='INFORMATION_SCHEMA',properties={'Cel':str(ts)+'.'+str(tn)})
        for label,fn in [('Definicje widoków',view_defs),('Wyzwalacze',triggers),('Sekwencje',sequences),('Procedury i funkcje',routines),('Domeny',domains),('Synonimy',synonyms)]:self.section(label,fn)
        self.section_state['Obiekty']='complete'
    def read_oracle(self):
        # Count dictionary objects before transferring their names or any bulk
        # metadata. A scope failure still proves that the connection succeeded.
        counts=self.rows('SELECT OWNER,COUNT(*) FROM ALL_OBJECTS WHERE SUBOBJECT_NAME IS NULL GROUP BY OWNER ORDER BY OWNER')
        self._oracle_scope={'schema':self.schema,'schemas':[{'name':str(owner),'objects':int(count)} for owner,count in counts],
                            'limit':DATABASE_MAX_OBJECTS}
        count=sum(item['objects'] for item in self._oracle_scope['schemas'] if not self.schema or item['name']==self.schema)
        scope='schemat '+self.schema if self.schema else 'wszystkie dostępne schematy'
        self.scopes=['Oracle · ALL_* · '+scope+' · obiekty widoczne dla zalogowanego konta, nie pełny katalog DBA.']
        if count>DATABASE_MAX_OBJECTS:
            message=f'Zakres „{scope}” obejmuje {count:,} obiektów; limit katalogu wynosi {DATABASE_MAX_OBJECTS:,}.'
            message+=(' Wybierz mniejszy schemat. Odczyt części pojedynczego schematu nie jest jeszcze dostępny.' if self.schema else
                      ' Wybierz schemat przed odczytem struktury.')
            raise DatabaseCatalogLimit(message,self._oracle_scope)
        params=[self.schema] if self.schema else []
        where=' WHERE OWNER=:p1' if self.schema else ''
        for owner,name,typ,status in self.rows('SELECT OWNER,OBJECT_NAME,OBJECT_TYPE,STATUS FROM ALL_OBJECTS WHERE SUBOBJECT_NAME IS NULL'+
                (' AND OWNER=:p1' if self.schema else ''),params):
            self.add(typ.lower(),owner,name,system=owner in ('SYS','SYSTEM'),properties={'Stan':status})
        def columns():
            for sc,tn,n,typ,pos,nullable,default,precision,scale in self.rows('SELECT OWNER,TABLE_NAME,COLUMN_NAME,DATA_TYPE,COLUMN_ID,NULLABLE,DATA_DEFAULT,DATA_PRECISION,DATA_SCALE FROM ALL_TAB_COLUMNS'+where+' ORDER BY OWNER,TABLE_NAME,COLUMN_ID',params):
                obj=self.relation(sc,tn)
                if obj:obj['columns'].append({'name':n,'type':typ+('('+str(precision)+(','+str(scale) if scale is not None else '')+')' if precision is not None else ''),
                    'position':int(pos or 0),'nullable':nullable=='Y','default':database_metadata_text(default),
                    'pk_position':0,'hidden':False,'generated':False})
        self.section('Kolumny',columns)
        def constraints():
            usage=collections.defaultdict(list)
            for sc,n,c,pos in self.rows('SELECT OWNER,CONSTRAINT_NAME,COLUMN_NAME,POSITION FROM ALL_CONS_COLUMNS'+where+' ORDER BY POSITION',params):
                usage[(sc,n)].append(c)
            rows=self.rows('SELECT OWNER,CONSTRAINT_NAME,CONSTRAINT_TYPE,TABLE_NAME,R_OWNER,R_CONSTRAINT_NAME,DELETE_RULE,STATUS,VALIDATED,SEARCH_CONDITION FROM ALL_CONSTRAINTS'+where,params)
            lookup={(r[0],r[1]):r[3] for r in rows}
            if self.schema and any(r[2]=='R' and r[4]!=self.schema for r in rows):
                # Read only external keys referenced from this schema. Their
                # labels remain useful even though their tables are out of scope.
                # DISTINCT prevents duplicate columns when several FKs share a key.
                sql=('SELECT DISTINCT p.OWNER,p.CONSTRAINT_NAME,p.TABLE_NAME,c.COLUMN_NAME,c.POSITION '
                     'FROM ALL_CONSTRAINTS f JOIN ALL_CONSTRAINTS p ON p.OWNER=f.R_OWNER AND p.CONSTRAINT_NAME=f.R_CONSTRAINT_NAME '
                     'LEFT JOIN ALL_CONS_COLUMNS c ON c.OWNER=p.OWNER AND c.CONSTRAINT_NAME=p.CONSTRAINT_NAME '
                     "WHERE f.OWNER=:p1 AND f.CONSTRAINT_TYPE='R' AND p.OWNER<>:p2 "
                     'ORDER BY p.OWNER,p.CONSTRAINT_NAME,c.POSITION')
                for sc,n,tn,col,pos in self.rows(sql,[self.schema,self.schema]):
                    lookup[(sc,n)]=tn
                    if col is not None:usage[(sc,n)].append(col)
            for sc,n,kind,tn,rsc,rn,dr,status,validated,expr in rows:
                obj=self.relation(sc,tn)
                if not obj:continue
                key={'name':n,'kind':{'P':'PRIMARY KEY','U':'UNIQUE','R':'FOREIGN KEY','C':'CHECK'}.get(kind,kind),
                     'columns':usage[(sc,n)],'enforced':status=='ENABLED','validated':validated}
                if kind=='C':key['expression']=database_metadata_text(expr)
                if kind=='R':
                    key.update(target_schema=rsc or '',target_table=lookup.get((rsc,rn),''),target_columns=usage[(rsc,rn)],on_delete=dr,on_update='NO ACTION')
                obj['keys'].append(key)
        self.section('Klucze i ograniczenia',constraints)
        def indexes():
            for sc,n,ts,tn,unique,typ in self.rows('SELECT OWNER,INDEX_NAME,TABLE_OWNER,TABLE_NAME,UNIQUENESS,INDEX_TYPE FROM ALL_INDEXES'+where,params):
                obj=self.add('index',sc,n,parent=tn,properties={'Rodzaj':typ,'Unikalny':unique=='UNIQUE'},index_columns=[])
                table=self.relation(ts,tn)
                if table:table['indexes'].append(obj['id'])
            for sc,n,c,pos,desc in self.rows('SELECT INDEX_OWNER,INDEX_NAME,COLUMN_NAME,COLUMN_POSITION,DESCEND FROM ALL_IND_COLUMNS'+
                    (' WHERE INDEX_OWNER=:p1' if self.schema else '')+' ORDER BY COLUMN_POSITION',params):
                obj=self.objects.get(database_object_id(sc,'index',n))
                if obj:obj.setdefault('index_columns',[]).append({'name':c,'position':int(pos),'direction':desc,'key':True})
        self.section('Indeksy',indexes)
        def definitions():
            for sc,n,text in self.rows('SELECT OWNER,VIEW_NAME,TEXT FROM ALL_VIEWS'+where,params):
                obj=self.relation(sc,n)
                if obj:obj.update(definition=database_metadata_text(text),definition_kind='view query')
            for sc,n,tn,event,timing,text in self.rows('SELECT OWNER,TRIGGER_NAME,TABLE_NAME,TRIGGERING_EVENT,TRIGGER_TYPE,TRIGGER_BODY FROM ALL_TRIGGERS'+where,params):
                self.add('trigger',sc,n,parent=tn or '',definition=database_metadata_text(text),definition_kind='body',properties={'Zdarzenie':event,'Rodzaj':timing})
        self.section('Definicje widoków i wyzwalaczy',definitions)
        self.section_state['ALL_OBJECTS']='complete'
    def read_firebird(self):
        self.scopes=['Firebird · katalog RDB$ otwartej bazy. Dostęp do treści obiektów zależy od uprawnień konta.']
        strip=lambda x:str(x or '').rstrip()
        for name,is_view,system,src in self.rows('SELECT RDB$RELATION_NAME,RDB$VIEW_BLR,RDB$SYSTEM_FLAG,RDB$VIEW_SOURCE FROM RDB$RELATIONS'):
            self.add('view' if is_view is not None else 'table','',strip(name),system=bool(system),
                definition=database_metadata_text(src),definition_kind='view query' if src else 'unavailable')
        def columns():
            types={7:'SMALLINT',8:'INTEGER',10:'FLOAT',12:'DATE',13:'TIME',14:'CHAR',16:'BIGINT',23:'BOOLEAN',24:'DECFLOAT(16)',25:'DECFLOAT(34)',26:'INT128',27:'DOUBLE',28:'TIME WITH TIME ZONE',29:'TIMESTAMP WITH TIME ZONE',35:'TIMESTAMP',37:'VARCHAR',261:'BLOB'}
            for tn,n,pos,typ,sub,scale,ln,nullable,default,computed in self.rows('SELECT r.RDB$RELATION_NAME,r.RDB$FIELD_NAME,r.RDB$FIELD_POSITION,f.RDB$FIELD_TYPE,f.RDB$FIELD_SUB_TYPE,f.RDB$FIELD_SCALE,f.RDB$CHARACTER_LENGTH,COALESCE(r.RDB$NULL_FLAG,f.RDB$NULL_FLAG,0),COALESCE(r.RDB$DEFAULT_SOURCE,f.RDB$DEFAULT_SOURCE),f.RDB$COMPUTED_SOURCE FROM RDB$RELATION_FIELDS r JOIN RDB$FIELDS f ON f.RDB$FIELD_NAME=r.RDB$FIELD_SOURCE ORDER BY r.RDB$FIELD_POSITION'):
                obj=self.relation('',strip(tn));t=types.get(typ,str(typ))
                if sub in (1,2) and typ in (7,8,16,26):t=('NUMERIC' if sub==1 else 'DECIMAL')+' · scale '+str(scale)
                elif ln is not None:t+='('+str(ln)+')'
                if obj:obj['columns'].append({'name':strip(n),'type':t,'position':int(pos)+1,'nullable':not bool(nullable),
                    'default':database_metadata_text(default),'pk_position':0,'hidden':False,'generated':computed is not None})
        self.section('Kolumny',columns)
        def keys_indexes():
            parts=collections.defaultdict(list)
            for n,c,pos in self.rows('SELECT RDB$INDEX_NAME,RDB$FIELD_NAME,RDB$FIELD_POSITION FROM RDB$INDEX_SEGMENTS ORDER BY RDB$FIELD_POSITION'):parts[strip(n)].append(strip(c))
            for n,tn,unique,desc,system,expr in self.rows('SELECT RDB$INDEX_NAME,RDB$RELATION_NAME,RDB$UNIQUE_FLAG,RDB$INDEX_TYPE,RDB$SYSTEM_FLAG,RDB$EXPRESSION_SOURCE FROM RDB$INDICES'):
                n,tn=strip(n),strip(tn);obj=self.add('index','',n,parent=tn,system=bool(system),definition=database_metadata_text(expr),definition_kind='expression' if expr else 'unavailable',
                    properties={'Unikalny':bool(unique)},index_columns=[{'name':c,'position':i+1,'direction':'DESC' if desc else 'ASC','key':True} for i,c in enumerate(parts[n])])
                table=self.relation('',tn)
                if table:table['indexes'].append(obj['id'])
            rows=self.rows('SELECT RDB$CONSTRAINT_NAME,RDB$CONSTRAINT_TYPE,RDB$RELATION_NAME,RDB$INDEX_NAME FROM RDB$RELATION_CONSTRAINTS')
            lookup={strip(r[0]):r for r in rows}
            refs={strip(n):(strip(t),strip(u),strip(d)) for n,t,u,d in self.rows('SELECT RDB$CONSTRAINT_NAME,RDB$CONST_NAME_UQ,RDB$UPDATE_RULE,RDB$DELETE_RULE FROM RDB$REF_CONSTRAINTS')}
            for n,kind,tn,idx in rows:
                n,kind,tn,idx=map(strip,(n,kind,tn,idx));obj=self.relation('',tn)
                if not obj:continue
                key={'name':n,'kind':kind,'columns':parts[idx]}
                if n in refs:
                    target,ur,dr=refs[n];r=lookup.get(target)
                    key.update(target_schema='',target_table=strip(r[2]) if r else '',target_columns=parts[strip(r[3])] if r else [],on_update=ur,on_delete=dr)
                obj['keys'].append(key)
        self.section('Klucze i indeksy',keys_indexes)
        def triggers():
            for n,tn,typ,inactive,system,src in self.rows('SELECT RDB$TRIGGER_NAME,RDB$RELATION_NAME,RDB$TRIGGER_TYPE,RDB$TRIGGER_INACTIVE,RDB$SYSTEM_FLAG,RDB$TRIGGER_SOURCE FROM RDB$TRIGGERS'):
                self.add('trigger','',strip(n),parent=strip(tn),system=bool(system),definition=database_metadata_text(src),definition_kind='source' if src else 'unavailable',properties={'Kod typu':str(typ),'Nieaktywny':bool(inactive)})
        def sequences():
            for n,system in self.rows('SELECT RDB$GENERATOR_NAME,RDB$SYSTEM_FLAG FROM RDB$GENERATORS'):
                self.add('sequence','',strip(n),system=bool(system))
        def procedures():
            for n,package,system,src in self.rows('SELECT RDB$PROCEDURE_NAME,RDB$PACKAGE_NAME,RDB$SYSTEM_FLAG,RDB$PROCEDURE_SOURCE FROM RDB$PROCEDURES'):
                name=(strip(package)+'.' if package else '')+strip(n)
                self.add('procedure','',name,parent=strip(package),system=bool(system),definition=database_metadata_text(src),definition_kind='source' if src else 'unavailable')
        def functions():
            for n,package,system,src in self.rows('SELECT RDB$FUNCTION_NAME,RDB$PACKAGE_NAME,RDB$SYSTEM_FLAG,RDB$FUNCTION_SOURCE FROM RDB$FUNCTIONS'):
                name=(strip(package)+'.' if package else '')+strip(n)
                self.add('function','',name,parent=strip(package),system=bool(system),definition=database_metadata_text(src),definition_kind='source' if src else 'unavailable')
        def packages():
            for n,system,header,body in self.rows('SELECT RDB$PACKAGE_NAME,RDB$SYSTEM_FLAG,RDB$PACKAGE_HEADER_SOURCE,RDB$PACKAGE_BODY_SOURCE FROM RDB$PACKAGES'):
                text='-- HEADER\n'+database_metadata_text(header)+'\n-- BODY\n'+database_metadata_text(body)
                self.add('package','',strip(n),system=bool(system),definition=text,definition_kind='package source')
        def domains():
            for n,system,typ,default,validation in self.rows('SELECT RDB$FIELD_NAME,RDB$SYSTEM_FLAG,RDB$FIELD_TYPE,RDB$DEFAULT_SOURCE,RDB$VALIDATION_SOURCE FROM RDB$FIELDS'):
                self.add('domain','',strip(n),system=bool(system) or strip(n).startswith('RDB$'),
                    definition=database_metadata_text(validation),definition_kind='validation' if validation else 'unavailable',
                    properties={'Kod typu':str(typ),'Domyślnie':database_metadata_text(default)})
        for label,fn in [('Wyzwalacze',triggers),('Sekwencje',sequences),('Procedury',procedures),('Funkcje',functions),('Pakiety',packages),('Domeny',domains)]:self.section(label,fn)
        self.section_state['RDB$RELATIONS']='complete'


def database_relation_meta(adapter, obj):
    """Resolve identifiers against the current database before generating a SELECT."""
    schema=str(obj.get('schema',''));name=str(obj.get('name',''))
    if not name or len(name)>512 or '\0' in name+schema:raise UserError('Nieprawidłowy obiekt bazy.')
    a=adapter
    if a.kind=='sqlite':
        if schema not in ('','main'):raise UserError('Ta sesja otwiera wyłącznie bazę main.')
        found=a.fetch("SELECT type FROM main.sqlite_schema WHERE name=? AND type IN ('table','view')",[name],1)
        if not found:raise UserError('Tabela lub widok nie istnieje. Odśwież strukturę bazy.')
        a.conn.set_authorizer(sqlite_metadata_authorizer)
        try:
            raw=a.fetch("PRAGMA main.table_xinfo('"+name.replace("'","''")+"')",limit=2500)
            cols=[{'name':r[1],'type':r[2] or '', 'pk_position':int(r[5])} for r in raw if r[6]!=1]
        finally:a.conn.set_authorizer(sqlite_authorizer)
    else:
        # Metadata, never a sample SELECT for datatype discovery.
        if a.kind=='h2':
            raw=a.fetch('SELECT COLUMN_NAME,DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME=? ORDER BY ORDINAL_POSITION',[schema or 'PUBLIC',name],2500)
        elif a.kind=='oracle':
            raw=a.fetch('SELECT COLUMN_NAME,DATA_TYPE FROM ALL_TAB_COLUMNS WHERE OWNER=:p1 AND TABLE_NAME=:p2 ORDER BY COLUMN_ID',[schema,name],2500)
        elif a.kind=='firebird':
            raw=a.fetch('SELECT TRIM(r.RDB$FIELD_NAME),f.RDB$FIELD_TYPE FROM RDB$RELATION_FIELDS r JOIN RDB$FIELDS f ON f.RDB$FIELD_NAME=r.RDB$FIELD_SOURCE WHERE r.RDB$RELATION_NAME=? ORDER BY r.RDB$FIELD_POSITION',[name],2500)
        else:raise UserError('Nieobsługiwane źródło.')
        cols=[{'name':str(n),'type':str(t),'pk_position':0} for n,t in raw]
    if not cols:raise UserError('Nie odczytano kolumn obiektu. Sprawdź uprawnienia i odśwież strukturę.')
    return cols


def database_exact_decimal(adapter, column):
    return adapter.kind=='sqlite' and 'DECIMAL_TEXT' in str(column.get('type','')).upper()


def database_order_expression(adapter, column, expression):
    return expression+(' COLLATE PS_DECIMAL' if database_exact_decimal(adapter,column) else '')


def database_page(adapter, args):
    """One bounded live page. Filters/sort run at source, not on an arbitrary sample.

    Page offsets are positions, not persistent row IDs. With concurrent writes,
    subsequent pages may change; a page is not advertised as an offline snapshot.
    """
    obj=args.get('object',{});cols=database_relation_meta(adapter,obj);names={c['name']:c for c in cols}
    offset=max(0,int(args.get('offset',0)))
    if offset>100000000:raise UserError('Zbyt odległa strona; zawęź dane filtrem.')
    limit=max(1,min(int(args.get('limit',DATABASE_PAGE_SIZE)),DATABASE_PAGE_SIZE,max(1,20000//len(cols))))
    params=[]
    def bind(value):params.append(value);return adapter.bind(len(params))
    clauses=[]
    for item in args.get('filters',[]):
        if len(clauses)>=16:raise UserError('Maksymalnie 16 filtrów przeglądu.')
        name=item.get('column');op=item.get('op','contains')
        if name not in names:raise UserError('Filtr wskazuje nieistniejącą kolumnę.')
        expr='ps_db.'+qident(name)
        if op in ('is_null','not_null'):clauses.append(expr+(' IS NULL' if op=='is_null' else ' IS NOT NULL'));continue
        raw=item.get('value','')
        if not isinstance(raw,(str,int,float)) or len(str(raw))>4096:raise UserError('Nieprawidłowa wartość filtra.')
        if op=='contains':
            # LIKE wildcards typed by user are literal, including the escape itself.
            text=str(raw).replace('!','!!').replace('%','!%').replace('_','!_')
            if adapter.kind=='oracle':expr='TO_CHAR('+expr+')'
            else:expr='CAST('+expr+(' AS TEXT)' if adapter.kind=='sqlite' else ' AS VARCHAR(8191))')
            clauses.append(expr+' LIKE '+bind('%'+text+'%')+" ESCAPE '!'")
        elif op in ('eq','ne','lt','gt','le','ge'):
            exact=database_exact_decimal(adapter,names[name])
            if item.get('numeric') or exact:
                try:raw=Decimal(str(raw))
                except decimal.InvalidOperation:raise UserError('Filtr liczbowy wymaga liczby.') from None
                if not raw.is_finite():raise UserError('Filtr wymaga skończonej liczby.')
                if adapter.kind=='sqlite':raw=str(raw)
            operator={'eq':' = ','ne':' <> ','lt':' < ','gt':' > ','le':' <= ','ge':' >= '}[op]
            param=bind(raw)
            clauses.append(f'ps_cmp({expr}, {param})'+operator+'0' if exact else expr+operator+param)
        else:raise UserError('Nieobsługiwany filtr przeglądu.')
    exprs=[]
    for col in cols:
        alias=qident(col['name']);name='ps_db.'+alias
        if adapter.kind=='sqlite':
            # Avoid transferring large binary values in a general-purpose preview.
            name=(f"CASE WHEN typeof({name})='blob' THEN '[BLOB: '||length({name})||' bajtów]' "
                  f"WHEN typeof({name})='text' AND length({name})>{MAX_CELL_TEXT} THEN substr({name},1,{MAX_CELL_TEXT-40})||' … [tekst skrócony w podglądzie]' ELSE {name} END AS {alias}")
        exprs.append(name)
    dataset={'schema':obj.get('schema',''),'table':obj['name']}
    sql='SELECT '+', '.join(exprs)+' FROM '+adapter.relation(dataset)+' ps_db'
    if clauses:sql+=' WHERE '+' AND '.join(clauses)
    sort=args.get('sort','');direction='DESC' if args.get('direction')=='desc' else 'ASC'
    if sort and sort not in names:raise UserError('Kolumna sortowania zniknęła. Odśwież strukturę.')
    primary=[c['name'] for c in sorted(cols,key=lambda c:c['pk_position']) if c['pk_position']]
    # Database keys reported by catalog are accepted only if every member still exists.
    if not primary:
        pk=args.get('primary_key',[])
        if pk and all(isinstance(n,str) and n in names for n in pk):primary=list(pk)
    order=([database_order_expression(adapter,names[sort],'ps_db.'+qident(sort))+' '+direction] if sort else [])
    # Distinct text keys such as '1' and '1.0' tie numerically. Keep their
    # original key order as a final tie-break, also when sorting that same key.
    order+=['ps_db.'+qident(n)+' ASC' for n in primary if n!=sort or database_exact_decimal(adapter,names[n])]
    # Without a key, don't force a full sort (or try to sort a LOB column) just to open a table.
    if order:sql+=' ORDER BY '+', '.join(order)
    if adapter.kind in ('oracle','h2'):sql+=f' OFFSET {offset} ROWS FETCH NEXT {limit+1} ROWS ONLY'
    elif adapter.kind=='firebird':sql+=f' ROWS {offset+1} TO {offset+limit+1}'
    else:sql+=f' LIMIT {limit+1} OFFSET {offset}'
    cur=adapter.execute(sql,params)
    try:
        adapter.check_cancel();raw=cur.fetchmany(limit+1);adapter.check_cancel()
        def preview_value(value):
            if isinstance(value,(bytes,bytearray,memoryview)):return pack('[BLOB: '+str(len(value))+' bajtów]')
            if hasattr(value,'read'):return pack('[LOB — niepobrany w podglądzie]')
            if isinstance(value,str) and len(value)>MAX_CELL_TEXT:return pack(value[:MAX_CELL_TEXT-40]+' … [tekst skrócony w podglądzie]')
            return pack(value)
        values=[[preview_value(v) for v in row] for row in raw[:limit]]
    finally:cur.close()
    result={'object':obj,'columns':cols,'rows':values,'offset':offset,'limit':limit,'has_more':len(raw)>limit,
            'read_at':utcnow(),'sort':sort,'direction':args.get('direction','asc'),'filters':args.get('filters',[]),
            'stable_order':bool(primary),'scope':'Strona z żywej bazy. Numery to pozycje w widoku, nie identyfikatory rekordów.',
            'sql':sql,'parameters':[{ 'index':i+1,'value':str(v)} for i,v in enumerate(params)]}
    if len(dumps(result).encode('utf-8'))>12*1024*1024:raise UserError('Strona danych jest zbyt duża. Zmniejsz liczbę rekordów na stronę.')
    return result


def database_cell_text(cell):
    if cell is None:return 'NULL'
    if cell.get('t')=='b':return 'TRUE' if cell.get('v')=='true' else 'FALSE'
    return str(cell.get('v',''))


def database_graph_subset(catalog, query='', schema='', include_system=False, focus='', limit=120):
    """Deterministic bounded graph plan; full tree stays available, no guessed edges."""
    objects={o['id']:o for o in catalog.get('objects',[]) if o['kind'] in DATABASE_RELATIONS}
    ids=[k for k,o in objects.items() if (include_system or not o['system']) and (not schema or o['schema']==schema)
         and (not query or query.casefold() in (database_label(o)+' '+' '.join(c['name'] for c in o['columns'])).casefold())]
    if focus and focus in objects:
        neighbors={focus}
        for e in catalog.get('relations',[]):
            if focus in (e['source'],e['target']):neighbors.update((e['source'],e['target']))
        ids=[k for k in ids if k in neighbors]
    total=len(ids);ids=ids[:max(1,limit)];chosen=set(ids)
    edges=[e for e in catalog.get('relations',[]) if e['source'] in chosen and e['target'] in chosen]
    return {'objects':[objects[k] for k in ids],'relations':edges,'visible':len(ids),'total':total,
            'omitted':max(0,total-len(ids)),'unresolved':sum(not e['resolved'] for e in catalog.get('relations',[]))}


# ================= Relational views: explicit FK plans, no inferred joins =====
DATABASE_JOIN_VERSION = 1
DATABASE_JOIN_MAX_TABLES = 8
DATABASE_JOIN_MAX_COLUMNS = 200


class DatabaseJoinChoice(UserError):
    """A relationship choice is necessary, not an excuse to guess a join."""


def database_join_identifier(value):
    if not isinstance(value,str) or not value or len(value)>512 or any(ord(c)<32 for c in value):
        raise UserError('Nieprawidłowa nazwa obiektu lub pola w połączeniu.')
    return value


def database_join_object(raw):
    """Small serializable metadata contract. DDL, credentials and rows never belong here."""
    if not isinstance(raw,dict) or raw.get('kind') not in DATABASE_RELATIONS:
        raise UserError('Połączenie wymaga tabel lub widoków.')
    name=database_join_identifier(raw.get('name'));schema=raw.get('schema','')
    if schema:database_join_identifier(schema)
    if not isinstance(schema,str):raise UserError('Nieprawidłowy schemat połączenia.')
    oid=database_object_id(schema,raw['kind'],name)
    if raw.get('id',oid)!=oid:raise UserError('Identyfikator tabeli nie pasuje do jej nazwy.')
    columns=[];seen=set();raw_columns=raw.get('columns',[])
    if not isinstance(raw_columns,list) or not 1<=len(raw_columns)<=DATABASE_JOIN_MAX_COLUMNS:raise UserError('Nieprawidłowy katalog kolumn połączenia.')
    for c in raw_columns:
        if not isinstance(c,dict):raise UserError('Nieprawidłowa definicja kolumny.')
        if c.get('hidden'):continue
        n=database_join_identifier(c.get('name'))
        if n in seen:raise UserError('Powtórzona kolumna w metadanych połączenia.')
        seen.add(n);pk=c.get('pk_position',0)
        if type(pk) is not int or not 0<=pk<=DATABASE_JOIN_MAX_COLUMNS:raise UserError('Nieprawidłowa pozycja klucza.')
        columns.append({'name':n,'type':clean_text(c.get('type',''),200),'pk_position':pk,'nullable':bool(c.get('nullable',True))})
    if not columns or len(columns)>DATABASE_JOIN_MAX_COLUMNS:
        raise UserError('Połączenie wymaga pełnych metadanych; limit wynosi 200 kolumn wyniku.')
    return {'id':oid,'name':name,'schema':schema,'kind':raw['kind'],'columns':columns}


def database_join_edge(raw,objects):
    if not isinstance(raw,dict) or raw.get('declared') is not True or raw.get('resolved') is not True:
        raise UserError('Połączenie wymaga zadeklarowanego klucza obcego z odczytanymi kolumnami.')
    source,target=raw.get('source'),raw.get('target')
    if not isinstance(source,str) or not isinstance(target,str):raise UserError('Nieprawidłowe końce relacji.')
    if source not in objects or target not in objects:raise UserError('Relacja wskazuje tabelę spoza zaznaczenia.')
    if source==target:raise DatabaseJoinChoice('Połączenie tabeli z samą sobą wymaga dwóch ról/aliasów; zaznaczenie jednego węzła otwiera jego dane.')
    left,right=raw.get('source_columns'),raw.get('target_columns')
    if not isinstance(left,list) or not isinstance(right,list) or not left or len(left)!=len(right) or len(left)>64:
        raise UserError('Niepełny klucz wielokolumnowy. Odśwież strukturę.')
    if any(not isinstance(n,str) for n in left+right):raise UserError('Nieprawidłowe kolumny klucza.')
    if len(set(left))!=len(left) or len(set(right))!=len(right):raise UserError('Powtórzone kolumny klucza.')
    for names,oid in ((left,source),(right,target)):
        known={c['name'] for c in objects[oid]['columns']}
        if any(not isinstance(n,str) or n not in known for n in names):raise UserError('Kolumna relacji zniknęła ze struktury.')
    name=database_join_identifier(raw.get('name'))
    eid=digest([source,name,left])[:32]
    if raw.get('id')!=eid:raise UserError('Identyfikator relacji nie pasuje do jej definicji.')
    return {'id':eid,'name':name,'source':source,'target':target,'source_columns':list(left),'target_columns':list(right),
            'declared':True,'resolved':True}


def database_join_order(objects,edges,base):
    """Exactly one connected tree. No implicit bridge or ignored cycle predicate."""
    if base not in objects:raise UserError('Tabela podstawowa nie należy do połączenia.')
    if len(edges)!=len(objects)-1:
        raise DatabaseJoinChoice('Wybierz dokładnie jedną drogę łączącą tabele (bez cyklu). Każdy wybrany klucz jest używany w całości.')
    remaining={e['id']:e for e in edges};seen={base};steps=[]
    while remaining:
        candidates=[e for e in remaining.values() if (e['source'] in seen)!=(e['target'] in seen)]
        if not candidates:raise DatabaseJoinChoice('Zaznaczone tabele nie tworzą spójnego połączenia. Zaznacz potrzebną tabelę pośrednią; program nie wykonuje CROSS JOIN.')
        edge=min(candidates,key=lambda e:(database_label(objects[e['source']]),database_label(objects[e['target']]),e['id']))
        old=edge['source'] if edge['source'] in seen else edge['target'];new=edge['target'] if old==edge['source'] else edge['source']
        steps.append({'relation':edge['id'],'existing':old,'added':new,'may_expand':old==edge['target']})
        seen.add(new);remaining.pop(edge['id'])
    if seen!=set(objects):raise DatabaseJoinChoice('Brak wspólnej drogi relacji. Zaznacz także tabelę pośrednią.')
    return steps


def database_join_validate(raw):
    """Untrusted project/callback values are validated before building any SQL."""
    if not isinstance(raw,dict) or raw.get('version')!=DATABASE_JOIN_VERSION:raise UserError('Nieobsługiwana definicja połączenia tabel.')
    if raw.get('backend') not in ('sqlite','h2','firebird','oracle'):raise UserError('Nieznany silnik połączenia.')
    source_id=database_join_identifier(raw.get('source_id'))
    records=raw.get('objects')
    if not isinstance(records,list) or not 2<=len(records)<=DATABASE_JOIN_MAX_TABLES:raise UserError('Zaznacz od 2 do 8 powiązanych tabel.')
    objects={}
    for record in records:
        obj=database_join_object(record)
        if obj['id'] in objects:raise UserError('Ta sama tabela występuje dwukrotnie. Role self-join nie są jeszcze obsługiwane.')
        if raw['backend']=='sqlite' and obj['schema']!='main':raise UserError('SQLite: połączenie obejmuje wyłącznie main otwartego pliku.')
        objects[obj['id']]=obj
    if sum(len(o['columns']) for o in objects.values())>DATABASE_JOIN_MAX_COLUMNS:
        raise UserError('Wspólny wynik przekroczyłby 200 kolumn. Wybierz mniej tabel lub użyj własnego SQL z wyborem kolumn.')
    raw_edges=raw.get('relations')
    if not isinstance(raw_edges,list) or len(raw_edges)>DATABASE_JOIN_MAX_TABLES-1:raise UserError('Nieprawidłowy zestaw relacji.')
    edges=[database_join_edge(e,objects) for e in raw_edges]
    if len({e['id'] for e in edges})!=len(edges):raise UserError('Powtórzona relacja.')
    mode=raw.get('join_type','left')
    if mode not in ('left','inner'):raise UserError('Obsługiwane połączenia: wszystkie rekordy podstawy (LEFT) lub tylko dopasowane (INNER).')
    base=raw.get('base');steps=database_join_order(objects,edges,base)
    ordered=[base]+[s['added'] for s in steps]
    by_id={e['id']:e for e in edges}
    return {'version':DATABASE_JOIN_VERSION,'source_id':source_id,'backend':raw['backend'],'base':base,'join_type':mode,
        'objects':[objects[oid] for oid in ordered],'relations':[by_id[s['relation']] for s in steps]}


def database_join_plan(catalog,selected_ids,base=None,relation_ids=None,join_type='left'):
    if not isinstance(selected_ids,(list,tuple)) or any(not isinstance(k,str) for k in selected_ids):raise UserError('Nieprawidłowe zaznaczenie tabel.')
    ids=list(dict.fromkeys(selected_ids));lookup={o['id']:o for o in catalog.get('objects',[]) if o['kind'] in DATABASE_RELATIONS}
    if not 2<=len(ids)<=DATABASE_JOIN_MAX_TABLES:raise UserError('Wybierz od 2 do 8 tabel. Jedną tabelę otwierasz bez łączenia.')
    if any(k not in lookup for k in ids):raise UserError('Zaznaczenie nie występuje w aktualnym katalogu.')
    chosen=set(ids)
    edges=[e for e in catalog.get('relations',[]) if e['source'] in chosen and e['target'] in chosen and e['source']!=e['target']]
    if relation_ids is not None:
        if not isinstance(relation_ids,(list,tuple)) or len(set(relation_ids))!=len(relation_ids):raise UserError('Nieprawidłowy wybór relacji.')
        by_id={e['id']:e for e in edges}
        if any(k not in by_id for k in relation_ids):raise UserError('Wybrany klucz nie łączy zaznaczonych tabel.')
        edges=[by_id[k] for k in relation_ids]
    if any(not e.get('declared') or not e.get('resolved') for e in edges):
        raise DatabaseJoinChoice('Nie wszystkie kolumny relacji są dostępne. Odśwież strukturę i sprawdź uprawnienia; nie zgaduję kluczy.')
    if base is None:
        # A child->parent chain has one leaf-grain root. Stable, independent of
        # selection order, object positions and keyboard focus.
        parents={e['target'] for e in edges};roots=chosen-parents
        base=min(roots or chosen,key=lambda k:(database_label(lookup[k]).casefold(),k))
    return database_join_validate({'version':DATABASE_JOIN_VERSION,'source_id':catalog['source_id'],'backend':catalog['backend'],
        'objects':[lookup[k] for k in ids],'relations':edges,'base':base,'join_type':join_type})


def database_join_caption(plan):
    return ' + '.join(o['name'] for o in plan['objects'])


def database_join_description(plan):
    base=next(o['name'] for o in plan['objects'] if o['id']==plan['base'])
    text='Podstawa: '+base+' · '+('wszystkie rekordy podstawy (LEFT)' if plan['join_type']=='left' else 'tylko dopasowane (INNER)')
    return text


def database_join_warning(plan):
    objects={o['id']:o for o in plan['objects']}
    steps=database_join_order(objects,plan['relations'],plan['base'])
    if any(s['may_expand'] for s in steps):
        return 'Połączenie może zwielokrotnić wiersze podstawy (1:N). Nie sumuj powtórzonych wartości bez ustalenia poziomu miary.'
    return 'Wynik ma poziom rekordów podstawy, o ile klucze docelowe są unikalne. Wartości tabel nadrzędnych mogą się powtarzać; pivot nie jest modelem wielotabelowym Excela.'


def database_join_alias(label,used):
    """Portable identifiers <= 30 UTF-8 bytes, including older Oracle configurations."""
    alias=label
    if len(alias.encode('utf-8'))>30:alias=alias.encode('utf-8')[:20].decode('utf-8','ignore')+'_'+digest(label)[:9]
    if alias in used:alias='pole_'+digest([label,len(used)])[:24]
    used.add(alias);return alias


def database_join_compile(plan,adapter,preview=False):
    plan=database_join_validate(plan)
    if adapter.kind!=plan['backend'] or adapter.source['id']!=plan['source_id']:raise UserError('Plan należy do innego połączenia lub silnika.')
    objects={o['id']:o for o in plan['objects']};aliases={o['id']:'ps_j'+str(i) for i,o in enumerate(plan['objects'])}
    duplicate_names=collections.Counter(o['name'] for o in plan['objects']);used=set();columns=[];expressions=[]
    for obj in plan['objects']:
        prefix=database_label(obj) if duplicate_names[obj['name']]>1 else obj['name']
        for c in obj['columns']:
            label=prefix+' · '+c['name'];alias=database_join_alias(label,used);expr=aliases[obj['id']]+'.'+qident(c['name']);value=expr
            if preview and adapter.kind=='sqlite':
                value=(f"CASE WHEN typeof({expr})='blob' THEN '[BLOB: '||length({expr})||' bajtów]' "
                    f"WHEN typeof({expr})='text' AND length({expr})>{MAX_CELL_TEXT} THEN substr({expr},1,{MAX_CELL_TEXT-40})||' … [tekst skrócony w podglądzie]' ELSE {expr} END")
            expressions.append(value+' AS '+qident(alias))
            columns.append({'name':alias,'label':label,'type':c['type'],'pk_position':0,'origin':{'object_id':obj['id'],'column':c['name']},'expression':expr})
    root=objects[plan['base']]
    clause=' FROM '+adapter.relation({'schema':root['schema'],'table':root['name']})+' '+aliases[root['id']]
    by_id={e['id']:e for e in plan['relations']}
    for step in database_join_order(objects,plan['relations'],plan['base']):
        edge=by_id[step['relation']];added=objects[step['added']]
        # Referenced (parent) key is on the left: important for SQLite text
        # collations when the child's column declares a different collation.
        pairs=[aliases[edge['target']]+'.'+qident(t)+' = '+('+' if adapter.kind=='sqlite' else '')+aliases[edge['source']]+'.'+qident(s)
               for s,t in zip(edge['source_columns'],edge['target_columns'])]
        clause+=(' LEFT JOIN ' if plan['join_type']=='left' else ' INNER JOIN ')+adapter.relation({'schema':added['schema'],'table':added['name']})+' '+aliases[added['id']]+' ON '+' AND '.join(pairs)
    return {'sql':'SELECT '+', '.join(expressions)+clause,'columns':columns,'aliases':aliases,'plan':plan}


def database_live_foreign_keys(adapter,obj):
    """Targeted live FK metadata, not a full catalogue scan for every data page."""
    a=adapter;sc=obj['schema'];name=obj['name'];rows=[]
    if a.kind=='sqlite':
        a.conn.set_authorizer(sqlite_metadata_authorizer)
        try:raw=a.fetch("PRAGMA main.foreign_key_list('"+name.replace("'","''")+"')",limit=DATABASE_MAX_ITEMS)
        finally:a.conn.set_authorizer(sqlite_authorizer)
        for key,pos,target,source_col,target_col,*rest in raw:
            rows.append(('FK '+str(key+1),int(pos),'main',target,source_col,target_col))
    elif a.kind=='oracle':
        sql=('SELECT f.CONSTRAINT_NAME,s.POSITION,p.OWNER,p.TABLE_NAME,s.COLUMN_NAME,t.COLUMN_NAME '
             'FROM ALL_CONSTRAINTS f JOIN ALL_CONS_COLUMNS s ON s.OWNER=f.OWNER AND s.CONSTRAINT_NAME=f.CONSTRAINT_NAME '
             'JOIN ALL_CONSTRAINTS p ON p.OWNER=f.R_OWNER AND p.CONSTRAINT_NAME=f.R_CONSTRAINT_NAME '
             'JOIN ALL_CONS_COLUMNS t ON t.OWNER=p.OWNER AND t.CONSTRAINT_NAME=p.CONSTRAINT_NAME AND t.POSITION=s.POSITION '
             "WHERE f.CONSTRAINT_TYPE='R' AND f.OWNER=:p1 AND f.TABLE_NAME=:p2 ORDER BY f.CONSTRAINT_NAME,s.POSITION")
        rows=a.fetch(sql,[sc,name],DATABASE_MAX_ITEMS)
    elif a.kind=='h2':
        sql=('SELECT f.CONSTRAINT_NAME,s.ORDINAL_POSITION,p.TABLE_SCHEMA,p.TABLE_NAME,s.COLUMN_NAME,t.COLUMN_NAME '
             'FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS f '
             'JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE s ON s.CONSTRAINT_SCHEMA=f.CONSTRAINT_SCHEMA AND s.CONSTRAINT_NAME=f.CONSTRAINT_NAME '
             'JOIN INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=f.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME=f.CONSTRAINT_NAME '
             'JOIN INFORMATION_SCHEMA.TABLE_CONSTRAINTS p ON p.CONSTRAINT_SCHEMA=r.UNIQUE_CONSTRAINT_SCHEMA AND p.CONSTRAINT_NAME=r.UNIQUE_CONSTRAINT_NAME '
             'JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE t ON t.CONSTRAINT_SCHEMA=p.CONSTRAINT_SCHEMA AND t.CONSTRAINT_NAME=p.CONSTRAINT_NAME AND t.ORDINAL_POSITION=s.POSITION_IN_UNIQUE_CONSTRAINT '
             'WHERE f.TABLE_SCHEMA=? AND f.TABLE_NAME=? ORDER BY f.CONSTRAINT_NAME,s.ORDINAL_POSITION')
        rows=a.fetch(sql,[sc,name],DATABASE_MAX_ITEMS)
    elif a.kind=='firebird':
        sql=('SELECT TRIM(f.RDB$CONSTRAINT_NAME),s.RDB$FIELD_POSITION,TRIM(p.RDB$RELATION_NAME),TRIM(s.RDB$FIELD_NAME),TRIM(t.RDB$FIELD_NAME) '
             'FROM RDB$RELATION_CONSTRAINTS f JOIN RDB$REF_CONSTRAINTS r ON r.RDB$CONSTRAINT_NAME=f.RDB$CONSTRAINT_NAME '
             'JOIN RDB$RELATION_CONSTRAINTS p ON p.RDB$CONSTRAINT_NAME=r.RDB$CONST_NAME_UQ '
             'JOIN RDB$INDEX_SEGMENTS s ON s.RDB$INDEX_NAME=f.RDB$INDEX_NAME '
             'JOIN RDB$INDEX_SEGMENTS t ON t.RDB$INDEX_NAME=p.RDB$INDEX_NAME AND t.RDB$FIELD_POSITION=s.RDB$FIELD_POSITION '
             "WHERE f.RDB$CONSTRAINT_TYPE='FOREIGN KEY' AND f.RDB$RELATION_NAME=? ORDER BY f.RDB$CONSTRAINT_NAME,s.RDB$FIELD_POSITION")
        rows=[(n,p,'',tn,s,t) for n,p,tn,s,t in a.fetch(sql,[name],DATABASE_MAX_ITEMS)]
    grouped=collections.defaultdict(list)
    for n,pos,ts,tn,s,t in rows:grouped[str(n)].append((int(pos),str(ts or ''),str(tn),str(s),str(t) if t is not None else None))
    out=[]
    for name,records in grouped.items():
        records.sort();out.append({'name':name,'target_schema':records[0][1],'target_table':records[0][2],
            'source_columns':[r[3] for r in records],'target_columns':[r[4] for r in records]})
    return out


def database_join_verify(adapter,plan):
    """Verify all selected columns and used FKs on the same connection as the SELECT."""
    plan=database_join_validate(plan);live={};objects={o['id']:o for o in plan['objects']}
    for obj in plan['objects']:
        adapter.check_cancel();cols=database_relation_meta(adapter,obj);live[obj['id']]=cols
        if [c['name'] for c in cols]!=[c['name'] for c in obj['columns']]:
            raise UserError('Struktura tabeli '+database_label(obj)+' zmieniła się. Odśwież mapę i ponownie wybierz połączenie.')
        # Remote inspectors present types more richly than the low-level reader;
        # compare exact SQLite types, while all engines revalidate FK membership.
        if adapter.kind=='sqlite' and [(c['type'],c['pk_position']) for c in cols]!=[(c['type'],c['pk_position']) for c in obj['columns']]:
            raise UserError('Zmieniono typy lub klucz tabeli '+database_label(obj)+'. Odśwież strukturę.')
    normalize=(lambda s:str(s).translate(str.maketrans('ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'))) if adapter.kind=='sqlite' else str
    cache={}
    for edge in plan['relations']:
        source,target=objects[edge['source']],objects[edge['target']]
        if source['id'] not in cache:cache[source['id']]=database_live_foreign_keys(adapter,source)
        matches=[]
        for fk in cache[source['id']]:
            if normalize(fk['target_schema'])!=normalize(target['schema']) or normalize(fk['target_table'])!=normalize(target['name']):continue
            targets=fk['target_columns']
            if targets and all(x is None for x in targets):
                targets=[c['name'] for c in sorted(live[target['id']],key=lambda c:c['pk_position']) if c['pk_position']]
            if (list(map(normalize,fk['source_columns']))==list(map(normalize,edge['source_columns'])) and
                list(map(normalize,targets))==list(map(normalize,edge['target_columns']))):matches.append(fk)
        if not matches:raise UserError('Klucz '+edge['name']+' nie ma już tej samej definicji. Odczyt połączenia zatrzymano; odśwież mapę.')
    return live


def database_join_filters(adapter,columns,filters):
    mapping={c['name']:c for c in columns};clauses=[];params=[]
    if not isinstance(filters,list) or len(filters)>16:raise UserError('Maksymalnie 16 filtrów połączenia.')
    def bind(v):params.append(v);return adapter.bind(len(params))
    for item in filters:
        if not isinstance(item,dict) or item.get('column') not in mapping:raise UserError('Filtr wskazuje nieznane pole połączenia.')
        column=mapping[item['column']];expr=column['expression'];op=item.get('op','contains')
        if op in ('is_null','not_null'):clauses.append(expr+(' IS NULL' if op=='is_null' else ' IS NOT NULL'));continue
        value=item.get('value','')
        if not isinstance(value,(str,int,float)) or isinstance(value,bool) or len(str(value))>4096:raise UserError('Nieprawidłowa wartość filtra.')
        if op=='contains':
            value=str(value).replace('!','!!').replace('%','!%').replace('_','!_')
            expr='TO_CHAR('+expr+')' if adapter.kind=='oracle' else 'CAST('+expr+(' AS TEXT)' if adapter.kind=='sqlite' else ' AS VARCHAR(8191))')
            clauses.append(expr+' LIKE '+bind('%'+value+'%')+" ESCAPE '!'")
        elif op in ('eq','ne','lt','gt','le','ge'):
            exact=database_exact_decimal(adapter,column)
            if item.get('numeric') or exact:
                try:value=Decimal(str(value))
                except decimal.InvalidOperation:raise UserError('Filtr liczbowy wymaga liczby.') from None
                if not value.is_finite():raise UserError('Filtr wymaga skończonej liczby.')
                if adapter.kind=='sqlite':value=str(value)
            operator={'eq':' = ','ne':' <> ','lt':' < ','gt':' > ','le':' <= ','ge':' >= '}[op]
            param=bind(value)
            clauses.append(f'ps_cmp({expr}, {param})'+operator+'0' if exact else expr+operator+param)
        else:raise UserError('Nieobsługiwany filtr połączenia.')
    return (' WHERE '+' AND '.join('('+x+')' for x in clauses) if clauses else ''),params


def database_join_page(adapter,args):
    plan=database_join_validate(args.get('plan'))
    if adapter.kind!=plan['backend'] or adapter.source['id']!=plan['source_id']:raise UserError('Plan należy do innego źródła lub silnika.')
    live=database_join_verify(adapter,plan)
    compiled=database_join_compile(plan,adapter,preview=True);columns=compiled['columns'];sql=compiled['sql']
    where,params=database_join_filters(adapter,columns,args.get('filters',[]));sql+=where
    offset=max(0,int(args.get('offset',0)))
    if offset>100000000:raise UserError('Zbyt odległa strona; zawęź wynik filtrem.')
    limit=max(1,min(int(args.get('limit',DATABASE_PAGE_SIZE)),DATABASE_PAGE_SIZE,max(1,20000//len(columns))))
    names={c['name']:c for c in columns};sort=args.get('sort','');direction='DESC' if args.get('direction')=='desc' else 'ASC'
    if sort and sort not in names:raise UserError('Nieprawidłowe pole sortowania.')
    order=[database_order_expression(adapter,names[sort],names[sort]['expression'])+' '+direction] if sort else [];keys=[];stable=adapter.kind=='sqlite'
    for obj in plan['objects']:
        pk=[c['name'] for c in sorted(live[obj['id']],key=lambda c:c['pk_position']) if c['pk_position']]
        stable=stable and bool(pk) and all(not c['nullable'] for c in obj['columns'] if c['pk_position'])
        for name in pk:
            expr=compiled['aliases'][obj['id']]+'.'+qident(name)
            column=next(c for c in live[obj['id']] if c['name']==name)
            if not sort or expr!=names[sort]['expression'] or database_exact_decimal(adapter,column):keys.append(expr+' ASC')
    if order or keys:sql+=' ORDER BY '+', '.join(order+keys)
    if adapter.kind in ('oracle','h2'):sql+=f' OFFSET {offset} ROWS FETCH NEXT {limit+1} ROWS ONLY'
    elif adapter.kind=='firebird':sql+=f' ROWS {offset+1} TO {offset+limit+1}'
    else:sql+=f' LIMIT {limit+1} OFFSET {offset}'
    adapter.check_cancel();cur=adapter.execute(sql,params)
    try:
        raw=cur.fetchmany(limit+1);adapter.check_cancel()
        def value(v):
            if isinstance(v,(bytes,bytearray,memoryview)):return pack('[BLOB: '+str(len(v))+' bajtów]')
            if hasattr(v,'read'):return pack('[LOB — niepobrany w podglądzie]')
            if isinstance(v,str) and len(v)>MAX_CELL_TEXT:v=v[:MAX_CELL_TEXT-40]+' … [tekst skrócony w podglądzie]'
            return pack(v)
        rows=[[value(v) for v in row] for row in raw[:limit]]
    finally:cur.close();adapter.active_cursor=None
    result={'object':{'id':'join-'+digest(plan)[:24],'name':database_join_caption(plan),'kind':'join','schema':''},
        'columns':[{k:v for k,v in c.items() if k!='expression'} for c in columns],'rows':rows,
        'offset':offset,'limit':limit,'has_more':len(raw)>limit,'stable_order':stable,'read_at':utcnow(),
        'scope':'Połączone rekordy z żywej bazy; kolejne strony mogą się zmieniać przy równoległym zapisie. Filtry działają po JOIN (WHERE).',
        'plan':plan,'plan_fingerprint':digest(plan),'sql':sql,'parameters':[{'index':i+1,'value':str(v)} for i,v in enumerate(params)],
        'warning':database_join_warning(plan),'sort':sort,'direction':args.get('direction','asc'),'filters':args.get('filters',[])}
    if len(dumps(result).encode('utf-8'))>12*1024*1024:raise UserError('Strona jest zbyt duża. Zawęź połączenie lub liczbę rekordów.')
    return result


def database_saved_join(raw):
    if not isinstance(raw,dict):raise UserError('Nieprawidłowy zapis połączonego widoku.')
    plan=database_join_validate(raw.get('plan'));sid=clean_text(raw.get('id') or uid(),64)
    name=clean_text(raw.get('name') or database_join_caption(plan),100)
    # No rendered SQL or data is trusted/restored as executable source.
    return {'id':sid,'name':name,'plan':plan}


def database_graph_layout(objects,relations,sizes,available_width=1200):
    """Deterministic component-first layout using real node dimensions.

    Linked nodes sit in adjacent breadth-first layers. Disconnected components
    pack into shelves; no scene-wide shrink is needed to read the labels.
    The UI may preserve user positions instead of applying this suggestion.
    """
    lookup={o['id']:o for o in objects};neighbors={k:set() for k in lookup};incoming=collections.Counter()
    for edge in relations:
        s,t=edge['source'],edge['target']
        if s in lookup and t in lookup and s!=t:neighbors[s].add(t);neighbors[t].add(s);incoming[t]+=1
    key=lambda k:(database_label(lookup[k]).casefold(),k)
    todo=set(lookup);components=[]
    while todo:
        first=min(todo,key=key);found={first};q=collections.deque([first]);todo.remove(first)
        while q:
            for other in sorted(neighbors[q.popleft()] & todo,key=key):todo.remove(other);found.add(other);q.append(other)
        components.append(found)
    components.sort(key=lambda c:(-len(c),min(key(k) for k in c)))
    blocks=[]
    for component in components:
        roots=[k for k in component if not incoming[k]]
        root=min(roots or component,key=lambda k:(-len(neighbors[k]),key(k)))
        levels={root:0};q=collections.deque([root])
        while q:
            parent=q.popleft()
            for child in sorted(neighbors[parent],key=key):
                if child not in levels:levels[child]=levels[parent]+1;q.append(child)
        cols=collections.defaultdict(list)
        for k in component:cols[levels.get(k,0)].append(k)
        positions={};x=0;maxh=0
        for level,items in sorted(cols.items()):
            y=0;w=max(sizes[k][0] for k in items)
            for k in sorted(items,key=key):positions[k]=(x,y);y+=sizes[k][1]+30
            maxh=max(maxh,y-30);x+=w+92
        blocks.append((positions,max(0,x-92),maxh))
    x=y=24;shelf=0;result={};width=max(660,float(available_width)-48)
    for positions,w,h in blocks:
        if x>24 and x+w>width:x=24;y+=shelf+40;shelf=0
        for k,(px,py) in positions.items():result[k]=(x+px,y+py)
        x+=w+36;shelf=max(shelf,h)
    return result


# ======================== 5. IZOLACJA PROCESÓW I ANULOWANIE ===================
def worker_main():
    """Persistent worker; DB connections belong to its executor thread, never the UI."""
    inbox=queue.Queue(); state={'id':None,'adapter':None,'cancel':None}; lock=threading.Lock(); output_lock=threading.Lock()
    cancelled_ids=set()
    def send(value):
        with output_lock:
            sys.stdout.write(dumps(value)+'\n'); sys.stdout.flush()
    def runner():
        while True:
            request=inbox.get()
            if request is None: return
            jid=request['id']; event=threading.Event(); adapter=None
            with lock:
                state.update(id=jid,adapter=None,cancel=event)
                if jid in cancelled_ids: event.set(); cancelled_ids.discard(jid)
            progress=lambda text:send({'id':jid,'event':'progress','text':text})
            watchdog=None;connected=False
            try:
                if event.is_set(): raise Cancelled('Zadanie anulowano przed uruchomieniem.')
                operation=request['operation']; args=request.get('args',{})
                if operation=='workbook_stage':value=workbook_stage(args['path'],args['directory'],event,args.get('previous'))
                elif operation=='workbook_prepare':value=workbook_prepare_bundle(args['source'],args['selections'],args['directory'],event,progress,args.get('compatible',False))
                elif operation=='workbook_sample':value=workbook_sample(args['source'],args['sheet_id'],args.get('options',{}),request['output'],event)
                elif operation=='inspect_file': value=inspect_local_file(args['path'],event)
                elif operation=='import_preview': value=import_preview(args['path'],args['options'])
                elif operation=='import':
                    value=import_file(args['path'],args['options'],args['columns'],request['output'],event,progress,args.get('file_state'))
                elif operation=='export': value=export_result(args['result_path'],args['destination'],args['format'],event)
                else:
                    source=validate_source(request['source']); progress('Łączenie ze źródłem w trybie analitycznym')
                    adapter=ADAPTERS[source['kind']](source,request.get('password',''),request.get('runtime',{}),event,request.get('timeout',60))
                    if source['kind']=='xlsx': adapter.bind_dataset(args.get('dataset') or args.get('analysis',{}).get('dataset',{}))
                    with lock: state['adapter']=adapter
                    def expired():
                        event.set()
                        with contextlib.suppress(Exception): adapter.cancel()
                        progress('Przekroczono limit czasu. Wysłano żądanie anulowania; oczekiwanie na sterownik.')
                    watchdog=threading.Timer(request.get('timeout',60),expired); watchdog.daemon=True; watchdog.start()
                    adapter.connect();connected=True;adapter.check_cancel()
                    if operation=='database_catalog': value=DatabaseInspector(adapter,progress,schema=args.get('schema')).read()
                    elif operation=='database_page': value=database_page(adapter,args)
                    elif operation=='database_join_page': value=database_join_page(adapter,args)
                    elif operation=='tables': value=adapter.tables()
                    elif operation=='test':
                        value={'message':'Sterownik i połączenie działają; odczyt metadanych zakończony.',
                               'tables':len(adapter.tables()),'backend':source['kind']}
                    elif operation=='columns':
                        dataset=validate_dataset(args['dataset']); value=[c.as_dict() for c in adapter.columns(dataset)]
                    elif operation in ('pivot','preview','drill','plan'):
                        analysis=validate_analysis(args['analysis'])
                        if operation=='pivot': value=run_pivot(adapter,analysis,request['output'],progress)
                        elif operation in ('preview','drill'):
                            value=run_preview(adapter,analysis,request['output'],args.get('extra'),progress,operation=='drill')
                        else:
                            qb=QueryBuilder(adapter,analysis,adapter.columns(analysis['dataset']))
                            value=[query_metadata(*qb.query(rn,cn)) for rn,cn in grouping_levels(analysis)]
                    else: raise UserError('Nieznany typ zadania.')
                    adapter.check_cancel()
                # import_file already checks cancellation before its atomic
                # publication. A later request cannot undo a completed import.
                if event.is_set() and operation not in ('import','workbook_stage','workbook_prepare'): raise Cancelled('Anulowano. Wynik nie został przyjęty jako aktualny.')
                send({'id':jid,'event':'done','value':value})
            except Exception as exc:
                is_cancel=event.is_set() or isinstance(exc,Cancelled)
                message='Anulowano wykonanie lub przekroczono limit czasu. Poprzedni wynik zachowano.' if is_cancel else safe_error(exc,request.get('password',''))
                failure={'id':jid,'event':'error','message':message,'cancelled':is_cancel,'connected':connected}
                if isinstance(exc,DependencyError) and not is_cancel:failure['dependency']=exc.dependency
                if isinstance(exc,DatabaseCatalogLimit) and not is_cancel:failure['catalog_scope']=exc.catalog_scope
                send(failure)
            finally:
                if watchdog: watchdog.cancel()
                if adapter:
                    with contextlib.suppress(Exception): adapter.close()
                # Never retain passwords in idle workers.
                request.clear()
                with lock: state.update(id=None,adapter=None,cancel=None)
    thread=threading.Thread(target=runner,name='DatabaseExecutor',daemon=False); thread.start()
    try:
        for line in sys.stdin:
            if len(line)>MAX_BODY: continue
            try: message=json.loads(line)
            except (ValueError,TypeError): continue
            if message.get('operation')=='cancel':
                with lock:
                    if state['id']==message.get('id'):
                        if state['cancel']: state['cancel'].set()
                        adapter=state['adapter']
                    else:
                        cancelled_ids.add(message.get('id')); adapter=None
                if adapter:
                    with contextlib.suppress(Exception): adapter.cancel()
            elif message.get('operation')=='shutdown': break
            elif isinstance(message,dict) and 'id' in message: inbox.put(message)
    finally:
        with lock:
            if state['cancel']: state['cancel'].set()
            adapter=state['adapter']
        if adapter:
            with contextlib.suppress(Exception): adapter.cancel()
        inbox.put(None); thread.join()


class WorkerClient:
    def __init__(self,hub,key):
        self.hub=hub; self.key=key; self.busy=None; self.write_lock=threading.Lock()
        env=dict(os.environ); env['PYTHONIOENCODING']='utf-8'; env['PYTHONUNBUFFERED']='1'
        interpreter=Path(sys.executable)
        # pythonw.exe has no dependable stdio transport; workers use python.exe hidden.
        if os.name=='nt' and interpreter.name.lower()=='pythonw.exe' and interpreter.with_name('python.exe').is_file():
            interpreter=interpreter.with_name('python.exe')
        self.process=subprocess.Popen([str(interpreter),str(Path(__file__).resolve()),'--worker'],
                                      stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,
                                      text=True,encoding='utf-8',bufsize=1,env=env,creationflags=CREATE_NO_WINDOW)
        self.reader=threading.Thread(target=self._read,daemon=True); self.reader.start()
    def send(self,payload):
        serialized=dumps(payload)+'\n'
        if len(serialized.encode('utf-8'))>MAX_BODY:raise UserError('Zadanie przekracza limit metadanych. Ogranicz liczbę zachowanych wersji lub utwórz osobny projekt.')
        with self.write_lock:
            if self.process.poll() is not None: raise UserError('Proces sterownika zakończył się. Spróbuj ponownie.')
            self.process.stdin.write(serialized); self.process.stdin.flush()
    def _read(self):
        try:
            for line in self.process.stdout:
                try: message=json.loads(line)
                except ValueError: continue
                with self.hub.lock:
                    job=self.hub.jobs.get(message.get('id'))
                    if not job: continue
                    if message.get('event')=='progress': job['stage']=message.get('text','')
                    elif message.get('event')=='done':
                        job.update(status='done',value=message['value'],ended=utcnow()); self.busy=None
                    elif message.get('event')=='error':
                        job.update(status='cancelled' if message.get('cancelled') else 'error',
                                   error=message.get('message','Błąd sterownika'),ended=utcnow()); self.busy=None
                        if isinstance(message.get('dependency'),dict):job['dependency']=message['dependency']
                        if isinstance(message.get('catalog_scope'),dict):job['catalog_scope']=message['catalog_scope']
                        job['connected']=message.get('connected') is True
        finally:
            with self.hub.lock:
                if self.busy and self.busy in self.hub.jobs:
                    self.hub.jobs[self.busy].update(status='error',error='Proces sterownika nieoczekiwanie się zakończył. Nie przyjęto częściowego wyniku.')
                self.busy=None
    def close(self):
        with contextlib.suppress(Exception): self.send({'operation':'shutdown'})
        with contextlib.suppress(Exception): self.process.stdin.close()


class WorkerHub:
    def __init__(self): self.lock=threading.RLock(); self.workers={}; self.jobs={}
    def submit(self,operation,args,source=None,password='',runtime=None,output='',timeout=60):
        # H2 JVM / Oracle Thick profiles are isolated. At most four active processes.
        key=digest({'source':source,'runtime':runtime}) if source else ('workbook-io' if operation in ('workbook_stage','workbook_prepare') else 'local-files')
        with self.lock:
            worker=self.workers.get(key)
            if worker and worker.process.poll() is not None:
                worker.close(); del self.workers[key]; worker=None
            if worker and worker.busy: raise UserError('To źródło już wykonuje zadanie. Anuluj je lub poczekaj na jego zakończenie.')
            if worker is None:
                if len(self.workers)>=4:
                    idle=next((k for k,w in self.workers.items() if w.busy is None),None)
                    if idle is None: raise UserError('Osiągnięto limit czterech równoległych zadań.')
                    self.workers.pop(idle).close()
                worker=WorkerClient(self,key); self.workers[key]=worker
            jid=uid(); self.jobs[jid]={'id':jid,'operation':operation,'status':'running','stage':'Przygotowanie zadania',
                                     'created':utcnow(),'output':output,'worker':worker,'args':args,'source_id':source['id'] if source else ''}
            worker.busy=jid
            try:
                worker.send({'id':jid,'operation':operation,'args':args,'source':source,'password':password,
                             'runtime':runtime or {},'output':output,'timeout':timeout})
            except Exception:
                worker.busy=None; self.jobs[jid]['status']='error'; raise
            return jid
    def poll(self,jid):
        with self.lock:
            if jid not in self.jobs: raise UserError('Zadanie nie istnieje w tej sesji.')
            job=self.jobs[jid]
            return {k:v for k,v in job.items() if k not in ('worker','output','args','source_id')}
    def cancel(self,jid):
        with self.lock:
            job=self.jobs.get(jid)
            if job and job['status']=='running':
                job['stage']='Żądanie anulowania wysłane. Oczekiwanie na zakończenie operacji w sterowniku.'
                job['worker'].send({'operation':'cancel','id':jid})
        return {'ok':True}
    def running(self):
        with self.lock: return [j['id'] for j in self.jobs.values() if j['status']=='running']
    def close(self):
        for jid in self.running(): self.cancel(jid)
        with self.lock:
            for worker in self.workers.values(): worker.close()
        # Do not kill a JVM attached to an embedded H2 file.


# ======================== 6. SEKRETY I INSTALATOR ============================
class SecretStore:
    def __init__(self): self.memory={}
    @staticmethod
    def key(source): return digest({'kind':source['kind'],'options':source['options']})
    @staticmethod
    def backend():
        keyring=require_module('keyring','secrets'); backend=keyring.get_keyring()
        module=type(backend).__module__
        if not any(module.startswith(x) for x in ('keyring.backends.Windows','keyring.backends.macOS',
                                                  'keyring.backends.SecretService','keyring.backends.kwallet')):
            raise UserError('Nie wykryto obsługiwanego systemowego magazynu haseł. Użyj hasła wyłącznie w pamięci sesji.')
        return keyring
    def set(self,source,password,remember=False):
        key=self.key(source)
        if remember:
            try: self.backend().set_password('PivotStudio',key,password)
            except Exception as exc: raise UserError('Nie zapisano hasła w systemowym magazynie: '+safe_error(exc,password)) from exc
        self.memory[key]=password
    def get(self,source):
        key=self.key(source)
        if key in self.memory: return self.memory[key]
        try: return self.backend().get_password('PivotStudio',key) or ''
        except Exception: return ''
    def forget(self,source):
        key=self.key(source); self.memory.pop(key,None)
        try: self.backend().delete_password('PivotStudio',key)
        except Exception: pass


