def _license_text(value, limit=2000):
    text=str(value or '')
    return ''.join(ch if ch in '\n\t' or ord(ch)>=32 and ord(ch)!=127 else ' ' for ch in text)[:limit]


def _license_key(name):
    return re.sub(r'[-_.]+','-',str(name)).lower()


def _license_cancel(cancel):
    if cancel is not None and cancel.is_set():raise Cancelled('Odczyt wykazu anulowany.')


def _license_https(url):
    """Only absolute HTTPS documentation, never credentials, shell/file URLs."""
    try:
        if not isinstance(url,str) or len(url)>2048 or any(ch.isspace() or ord(ch)<32 for ch in url) or '\\' in url:return False
        u=urllib.parse.urlsplit(url);u.port
        return u.scheme=='https' and bool(u.hostname) and u.username is None and u.password is None and not u.query
    except ValueError:return False


def _license_row(name, version, license_name, role, *, group='Pakiety', present=True, status='Do weryfikacji', commercial='Do weryfikacji', terms='', proofs=(), expected='', origin=''):
    return dict(id=uid(),name=_license_text(name,160),version=_license_text(version,100),license=_license_text(license_name,240),
        role=_license_text(role),group=group,present=bool(present),status=status,commercial=commercial,
        terms=_license_text(terms,10000),expected_version=expected,origin=origin,review_date='',notices=[],
        proofs=[{'label':_license_text(label,120),'url':url} for label,url in proofs if _license_https(url)])


def _license_safe_file(root,path):
    """Reject all symbolic links/junctions and escapes, including parent links."""
    import stat
    root=Path(os.path.abspath(root));path=Path(os.path.abspath(path))
    try:relative=path.relative_to(root)
    except ValueError:raise UserError('Tekst licencji znajduje się poza zakresem odczytu.') from None
    for part in (root,*[root.joinpath(*relative.parts[:i]) for i in range(1,len(relative.parts)+1)]):
        if part.is_symlink() or getattr(part,'is_junction',lambda:False)():raise UserError('Odmowa odczytu licencji przez dowiązanie.')
    if not stat.S_ISREG(path.stat().st_mode):raise UserError('Wskazany składnik nie jest zwykłym plikiem.')
    return path


def _license_read_bytes(root,path,maximum=LICENSE_NOTICE_LIMIT):
    import stat
    path=_license_safe_file(root,path)
    fd=os.open(path,os.O_RDONLY|getattr(os,'O_NOFOLLOW',0)|getattr(os,'O_BINARY',0))
    with os.fdopen(fd,'rb') as stream:
        details=os.fstat(stream.fileno())
        if not stat.S_ISREG(details.st_mode) or details.st_size>maximum:raise UserError('Tekst licencji przekracza limit odczytu lub nie jest zwykłym plikiem.')
        data=stream.read(maximum+1)
    if len(data)>maximum:raise UserError('Tekst licencji przekracza limit odczytu.')
    if b'\0' in data:raise UserError('Nie otwarto binarnego pliku jako tekstu licencji.')
    return data


def _license_is_notice(name):
    path=Path(str(name));suffix=path.suffix.lower()
    if suffix in _LICENSE_DENIED_EXT:return False
    if _LICENSE_NOTICE_NAME.match(path.name):return True
    # Read texts in designated notice directories without inferring a license
    # from names such as MIT.txt or LGPL-3.0-only.txt.
    return suffix in ('','.txt','.md','.rst','.license') and any(part.lower() in ('licenses','licences','legal') for part in path.parts[:-1])


def _license_notice(root,path,budget):
    """A hash identifies the observed bytes; it never grants a license."""
    if budget['bytes']>=LICENSE_SCAN_BUDGET:raise UserError('Osiągnięto limit 16 MiB tekstów licencji.')
    data=_license_read_bytes(root,path,min(LICENSE_NOTICE_LIMIT,LICENSE_SCAN_BUDGET-budget['bytes']))
    budget['bytes']+=len(data)
    return {'label':Path(path).relative_to(root).as_posix(),'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data),
            '_root':str(Path(root).absolute()),'_path':str(Path(path).absolute())}


def read_license_notice(record):
    """Viewer entry point. A changed file must be rescanned, never blindly opened."""
    if not isinstance(record,dict) or not _license_is_notice(record.get('label','')):raise UserError('Nieprawidłowy wpis tekstu licencji.')
    if record.get('_archive'):
        path=_license_safe_file(record['_root'],record['_archive']);member=record['_member']
        if path.stat().st_size>256*1024*1024:raise UserError('Archiwum przekracza limit odczytu.')
        with zipfile.ZipFile(path) as archive:
            info=archive.getinfo(member)
            if info.file_size>LICENSE_NOTICE_LIMIT or info.flag_bits&1:raise UserError('Niedostępny tekst w archiwum.')
            with archive.open(info) as stream:data=stream.read(LICENSE_NOTICE_LIMIT+1)
    else:data=_license_read_bytes(record['_root'],record['_path'])
    if len(data)>LICENSE_NOTICE_LIMIT or b'\0' in data or hashlib.sha256(data).hexdigest()!=record.get('sha256'):
        raise UserError('Tekst licencji zmienił się od odczytu. Odśwież wykaz przed otwarciem.')
    return data.decode('utf-8-sig','replace')


def _license_package_row(dist, expected=None):
    meta=dist.metadata;name=_license_text(meta.get('Name') or 'Nieznany pakiet',160)
    version=_license_text(dist.version,100);declared=_license_text(meta.get('License-Expression') or meta.get('License') or '',500)
    declared=' '.join(declared.split())
    classifiers=[str(x).removeprefix('License :: ') for x in (meta.get_all('Classifier') or []) if str(x).startswith('License :: ')]
    if not declared:declared='; '.join(classifiers) or 'Brak deklaracji w metadanych'
    proof=('Deklaracja wydawcy · '+version,'https://pypi.org/project/'+urllib.parse.quote(_license_key(name),safe='')+'/'+urllib.parse.quote(version,safe='')+'/')
    if expected:
        title,pinned,license_name,role=expected
        commercial,terms,url=_LICENSE_RULES.get(license_name,('Zależnie od składnika',
            'Wheel Essentials nie ma jednej licencji obejmującej wszystkie pliki. Moduły używane przez Pivot mają wariant LGPLv3, '
            'ale przy przekazywaniu całego pakietu uwzględnij także pozostałe moduły i zależności, w tym składniki GPL-only. '+_LICENSE_LGPL_TERMS,
            'https://doc.qt.io/qt-6/licensing.html'))
        status='Deklaracja wydawcy · ta wersja' if version==pinned else 'Wersja do weryfikacji'
        if version!=pinned:commercial='Do weryfikacji wersji'
        # Do not award a known permissive interpretation to a contradictory local
        # declaration (e.g. a differently packaged internal distribution).
        normalized=' '.join(declared.lower().split())
        accepted={'MIT':{'mit','mit license','mit license (mit license)','osi approved :: mit license'},
            'Apache-2.0':{'apache-2.0','apache 2.0','apache license 2.0','apache software license'},
            'UPL-1.0 OR Apache-2.0':{'upl-1.0 or apache-2.0','apache-2.0 or upl-1.0'},
            'LGPL-3.0-only':{'lgpl-3.0-only','lgpl-3.0','lgplv3','lgpl-3.0-only or gpl-3.0-only','licenseref-qt-commercial or lgpl-3.0-only or gpl-3.0-only'},
            'LGPL/GPL/commercial · per component':{'lgpl-3.0-only','lgpl-3.0','lgplv3','lgpl-3.0-only or gpl-3.0-only','licenseref-qt-commercial or lgpl-3.0-only or gpl-3.0-only'}}
        local_match=normalized in accepted.get(license_name,set())
        # SPDX OR is commutative. Only exact alternatives are accepted; AND,
        # arbitrary prose and expressions containing additional terms are not.
        choices=set(normalized.split(' or '))
        if license_name=='UPL-1.0 OR Apache-2.0':local_match=local_match or choices=={'upl-1.0','apache-2.0'}
        if license_name in ('LGPL-3.0-only','LGPL/GPL/commercial · per component'):
            allowed={'lgpl-3.0-only','gpl-2.0-only','gpl-2.0-or-later','gpl-3.0-only','gpl-3.0-or-later','licenseref-qt-commercial'}
            local_match=local_match or 'lgpl-3.0-only' in choices and choices<=allowed
        if version==pinned and not local_match:
            status='Rozbieżna deklaracja';commercial='Do weryfikacji'
            terms+=' Lokalna deklaracja jest nieobecna, odmienna lub niejednoznaczna; porównaj ją ze źródłem wydawcy.'
        row=_license_row(title,version,license_name,role,expected=pinned,status=status,commercial=commercial,terms=terms,
            proofs=(proof,('Warunki i składniki',url)),origin='Katalog wydawcy + lokalne metadane')
        row['review_date']=LICENSE_CATALOG_DATE
    else:
        row=_license_row(name,version,declared[:200],'Pakiet obecny w środowisku; nie oznacza, że aplikacja go używa.',
            group='Środowisko',terms='Deklaracja z lokalnych metadanych, bez niezależnej oceny tej wersji ani składników wbudowanych.',
            proofs=(proof,),origin='Wyłącznie lokalne metadane')
        if _license_key(name)=='pip':
            row.update(license='MIT + licencje składników',commercial='Sprawdź składniki',
                role='Narzędzie instalacyjne. Jego wbudowane biblioteki mają osobne licencje.',
                terms='Licencja samego pip nie zastępuje licencji pakietów w pip/_vendor. Sprawdź dołączone teksty i odpowiadające źródła.')
            row['proofs'].append({'label':'Polityka vendoringu','url':'https://pip.pypa.io/en/stable/development/vendoring-policy/'})
    row['metadata_license']=declared
    row['requires_python']=_license_text(meta.get('Requires-Python'),100)
    return row


