    class WheelGuard(QC.QObject):
        def eventFilter(self,obj,event):
            if event.type()==QC.QEvent.Type.Wheel and isinstance(obj,(QW.QComboBox,QW.QAbstractSpinBox)):
                if isinstance(obj,QW.QComboBox) and obj.view().isVisible():return False
                parent=obj.parentWidget()
                while parent and not isinstance(parent,QW.QAbstractScrollArea):parent=parent.parentWidget()
                if parent:
                    bar=parent.verticalScrollBar();delta=event.pixelDelta().y() or event.angleDelta().y()/120*35
                    bar.setValue(bar.value()-int(delta))
                event.accept();return True
            return False

    def label(text='', muted=False, wrap=False):
        widget=QW.QLabel(text); widget.setTextFormat(Qt.TextFormat.PlainText); widget.setWordWrap(wrap)
        if muted: widget.setObjectName('muted')
        return widget

    def combo(values, current=None):
        widget=QW.QComboBox()
        for key,text in values.items(): widget.addItem(text,key)
        if current is not None:
            i=widget.findData(current)
            if i>=0: widget.setCurrentIndex(i)
        widget.setSizeAdjustPolicy(QW.QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon)
        widget.setMinimumContentsLength(8)
        return widget

    def button(text, callback=None, primary=False):
        widget=QW.QPushButton(text);widget.setCursor(Qt.CursorShape.PointingHandCursor);widget.setAutoDefault(False)
        if primary: widget.setObjectName('primary')
