        def dispose(self):
            if self._closed:return
            self._closed=True;self._cancel.set();self._tasks.close()
        def closeEvent(self,event):self.dispose();super().closeEvent(event)
        def refresh(self):
            if self._closed:return
            self._cancel.set();self._cancel=threading.Event();self._epoch+=1;epoch=self._epoch;cancel=self._cancel;settings=dict(self._settings)
            self.count_label.setText('Odczytuję metadane i dołączone teksty. Bez sieci i bez dostępu do baz lub haseł.')
            self.refresh_button.setEnabled(False)
            def done(report):
                if self._closed or epoch!=self._epoch:return
                self._report=report;self.refresh_button.setEnabled(True);self.copy_button.setEnabled(True);self.export_button.setEnabled(True);self.populate()
            def failed(text):
                if self._closed or epoch!=self._epoch:return
                self.refresh_button.setEnabled(True);self.count_label.setText('Nie odczytano nowego wykazu: '+text)
            self._tasks.submit(lambda:collect_technology_inventory(settings,cancel),done,failed,'Technologie i licencje')
        def current_record(self):
            index=self.table.currentIndex()
            return self.inventory_model.records[index.row()] if index.isValid() and 0<=index.row()<len(self.inventory_model.records) else None
        def populate(self,*_):
            if self._closed or self._report is None:return
            current=self.current_record();key=current['id'] if current else ''
            rows=filter_technology_rows(self._report,self.search.text(),self.group.currentData() or '',self.only_installed.isChecked())
            self.inventory_model.set_records(rows)
            if rows:
                n=next((i for i,r in enumerate(rows) if r['id']==key),0);self.table.setCurrentIndex(self.inventory_model.index(n,0))
            self.count_label.setText(f'{len(rows)} z {len(self._report["rows"])} składników · katalog deklaracji {LICENSE_CATALOG_DATE}'+
                (f' · ograniczenia odczytu: {len(self._report["warnings"])}' if self._report['warnings'] else ''))
            self.count_label.setToolTip('\n'.join(self._report['warnings']));self.show_details()
        def show_details(self,*_):
            if self._closed:return
            row=self.current_record();self.proofs.clear();self.open_source.setEnabled(bool(row))
            if row is None:self.details.setPlainText('Brak pasujących składników.');return
            text=f'{row["name"]} · {row["version"]}\n{row["role"]}\n\nLicencja: {row["license"]}\n{row["commercial"]} — {row["status"]}\n\n{row["terms"]}'
            if row.get('expected_version'):text+='\n\nWersja opisana w katalogu: '+row['expected_version']
            if row.get('metadata_license'):text+='\nLokalna deklaracja wydawcy: '+row['metadata_license']
            if row.get('requires_python'):text+='\nWymagany Python: '+row['requires_python']
            text+='\n\n'+row.get('notice_status','Teksty składników wymagają osobnej kontroli.')
            if row['notices']:text+=' Hash identyfikuje odczytany tekst, nie potwierdza praw do dystrybucji.'
            self.details.setPlainText(text)
            for proof in row['proofs']:self.proofs.addItem(proof['label']+' ↗',{'url':proof['url']})
            for notice in row['notices']:self.proofs.addItem('Lokalnie: '+notice['label'],{'notice':notice})
            self.open_source.setEnabled(self.proofs.count()>0)
        def open_proof(self):
            entry=self.proofs.currentData()
            if not entry or self._closed:return
            if entry.get('url'):
                url=entry['url']
                if not _license_https(url):return
                if not QG.QDesktopServices.openUrl(QC.QUrl(url)):self.count_label.setText('Nie udało się otworzyć oficjalnego źródła.')
                return
            notice=dict(entry['notice'])
            def done(text):
                if self._closed:return
                dialog=QW.QDialog(self);dialog.setWindowTitle('Dołączona licencja · '+Path(notice['label']).name)
                layout=QW.QVBoxLayout(dialog);layout.setContentsMargins(20,18,20,18)
                layout.addWidget(label(notice['label'],False,True));layout.addWidget(label('SHA-256: '+notice['sha256'],True,True))
                view=QW.QPlainTextEdit();view.setReadOnly(True);view.setPlainText(text);layout.addWidget(view,1);layout.addWidget(button('Zamknij',dialog.accept))
                limited_dialog_size(dialog,850,630);dialog.exec()
            def failed(text):
                if not self._closed:self.count_label.setText(text)
            self._tasks.submit(lambda:read_license_notice(notice),done,failed,'Odczyt tekstu licencji')
        def copy_inventory(self):
            if self._report:
                QW.QApplication.clipboard().setText(technology_inventory_text(self._report));self.count_label.setText('Skopiowano pełny wykaz, także pozycje ukryte filtrem. Bez lokalizacji instalacji.')
        def export_inventory(self):
            if not self._report:return
            path=QW.QFileDialog.getSaveFileName(self,'Zapisz pełny wykaz','PivotStudio-technologie.json','JSON (*.json)')[0]
            if not path:return
            target=Path(path).with_suffix('.json').absolute()
            protected={Path(__file__).resolve()}
            if self._host_window.service.project_path:protected.add(Path(self._host_window.service.project_path).resolve())
            for source in self._host_window.service.document['sources']:
                if source['options'].get('path'):protected.add(Path(source['options']['path']).expanduser().resolve())
            try:
                if target.resolve() in protected:raise UserError('Wykaz nie może zastąpić aplikacji, projektu ani źródła danych.')
                if target.exists() and not confirm(self,'Zastąp wykaz','Zastąpić '+str(target)+'?'):return
                atomic_bytes(target,(json.dumps(public_technology_inventory(self._report),ensure_ascii=False,indent=2)+'\n').encode('utf-8'))
                self.count_label.setText('Zapisano pełny wykaz. Raport nie zawiera lokalizacji bibliotek ani ustawień połączeń.')
            except (OSError,UserError) as exc:self.count_label.setText(safe_error(exc))


