                form.setRowWrapPolicy(QW.QFormLayout.RowWrapPolicy.WrapLongRows)
                form.setFieldGrowthPolicy(QW.QFormLayout.FieldGrowthPolicy.AllNonFixedFieldsGrow)
                options=source['options'] if source and source['kind']==kind else {}; self.inputs[kind]={}
                for key,title,typ,default in fields:
                    value=options.get(key,default)
                    if typ=='path': widget=PathField(value,'Bazy danych (*.sqlite *.db *.sqlite3 *.mv.db);;Wszystkie pliki (*)')
                    elif typ=='port': widget=QW.QSpinBox(); widget.setRange(1,65535); widget.setValue(int(value))
                    elif typ=='h2mode': widget=combo({'file':'Plik lokalny — tylko odczyt','tcp':'Serwer TCP','ssl':'Serwer SSL'},value)
                    elif typ=='oraclemode': widget=combo({'thin':'Thin — bez Oracle Client','thick':'Thick — Oracle Client'},value)
                    else: widget=QW.QLineEdit(str(value))
                    form.addRow(title,widget); self.inputs[kind][key]=widget
                self.forms[kind]=(page,form); self.stack.addWidget(page)
