    class MeasureDialog(FormDialog):
        def __init__(self,fields,measures,value=None,parent=None):
            super().__init__('Miara',parent); self.existing=value or {}; value=value or {}; self.fields=fields
            self.field=combo({f['name']:f['name'] for f in fields},value.get('field'))
            self.agg=combo(AGG_NAMES,value.get('agg','sum')); self.title_edit=QW.QLineEdit(value.get('label',''))
            self.fmt=combo(FORMATS,value.get('format','auto'))
            base={m['id']:m.get('label') or (AGG_NAMES[m['agg']]+' · '+m.get('field','')) for m in measures if m['agg']!='ratio' and m['id']!=value.get('id')}
            self.numerator=combo(base,value.get('numerator')); self.denominator=combo(base,value.get('denominator'))
            self.form.addRow('Agregacja',self.agg); self.form.addRow('Pole',self.field); self.form.addRow('Nazwa miary',self.title_edit)
            self.form.addRow('Format',self.fmt); self.form.addRow('Licznik',self.numerator); self.form.addRow('Mianownik',self.denominator)
            self.agg.currentIndexChanged.connect(self.update_kind); self.update_kind()
            self.add_widget(label('Iloraz liczy stosunek zagregowanych miar. Sumy końcowe nie są sumą procentów ani średnich.',True,True))
            limited_dialog_size(self,550,405)
        def update_kind(self):
            agg=self.agg.currentData(); self.field.setEnabled(agg not in ('count_rows','ratio'))
            for widget in (self.numerator,self.denominator): widget.setEnabled(agg=='ratio')
        def read(self):
            agg=self.agg.currentData(); name=self.field.currentData() or ''
            if agg in ('sum','avg') and not next((f['kind']=='number' for f in self.fields if f['name']==name),False):
                raise UserError('Ta agregacja wymaga pola liczbowego.')
            if agg=='ratio' and (not self.numerator.currentData() or not self.denominator.currentData()):
                raise UserError('Najpierw dodaj dwie miary bazowe, potem ich iloraz.')
            return {'id':self.existing.get('id') or uid(),'field':name if agg not in ('ratio','count_rows') else '',
                    'agg':agg,'label':self.title_edit.text().strip(),'format':self.fmt.currentData(),
                    'numerator':self.numerator.currentData() or '','denominator':self.denominator.currentData() or ''}

    class FilterDialog(FormDialog):
        def __init__(self,fields,value=None,parent=None):
            super().__init__('Filtr źródła',parent); value=value or {}; self.fields=fields
            self.field=combo({f['name']:f['name'] for f in fields},value.get('field'))
