        def __init__(self,parent=None):
            super().__init__(parent); self.setAcceptDrops(True); self.setDragEnabled(True)
            self.setDragDropMode(QW.QAbstractItemView.DragDropMode.InternalMove)
            self.setDefaultDropAction(Qt.DropAction.MoveAction); self.setMinimumHeight(40); self.setMaximumHeight(125)
            self.model().rowsMoved.connect(lambda *args:QC.QTimer.singleShot(0,self.reordered.emit))
