        def _color_option(opt,foreground,background):
            fg,bg=QG.QColor(foreground),QG.QColor(background)
            for role in (QG.QPalette.ColorRole.Text,QG.QPalette.ColorRole.WindowText,
                         QG.QPalette.ColorRole.HighlightedText):
                opt.palette.setColor(QG.QPalette.ColorGroup.All,role,fg)
            for role in (QG.QPalette.ColorRole.Base,QG.QPalette.ColorRole.AlternateBase,
                         QG.QPalette.ColorRole.Window,QG.QPalette.ColorRole.Highlight):
                opt.palette.setColor(QG.QPalette.ColorGroup.All,role,bg)
            opt.backgroundBrush=QG.QBrush(bg)
