        def paint(self,painter,option,index):
            opt=QW.QStyleOptionViewItem(option);self.initStyleOption(opt,index)
            model=index.model();style=model.cell_style(index)
            selected=bool(opt.state & QW.QStyle.StateFlag.State_Selected)
            foreground,background=model.display_colors(index,selected=selected,current=index==self._grid.currentIndex())
            self._color_option(opt,foreground,background)
