            sh=self.active_sheet();value=max(20 if kind=='columns' else 16,min(2000 if kind=='columns' else 1000,size/(self.zoom.value()/100)))
            if abs(sh[kind].get(str(index),0)-value)<.5:return
            sh[kind][str(index)]=value
