                            bounds=fm.boundingRect(QC.QRectF(0,0,max(10,(self.views.left.columnWidth(c) if c<self.views.frozen[1] else self.grid.columnWidth(c))-10),10000),int(Qt.TextFlag.TextWordWrap),text)
                            height=max(height,math.ceil(min(bounds.height(),fm.lineSpacing()*8)+8))
