        def used_rect(self):
            if not self.session:return (0,0,0,0)
            coords=[sheet_position(a) for a,c in self.active_sheet()['cells'].items() if c.get('v') is not None or c.get('f') or c.get('error')]
            return (min((r for r,c in coords),default=0),min((c for r,c in coords),default=0),max((r for r,c in coords),default=0),max((c for r,c in coords),default=0))
        def selected_rect(self):
            selection=self.grid.selectionModel().selection()
            if not selection:
                index=self.grid.currentIndex()
                if not index.isValid():return (0,0,0,0)
                return index.row(),index.column(),index.row(),index.column()
