            self.grid.verticalHeader().setDefaultSectionSize(29);self.grid.verticalHeader().setMinimumWidth(42);self.grid.horizontalHeader().setDefaultSectionSize(160)
            self.grid.horizontalHeader().setSectionsClickable(True);self.grid.horizontalHeader().sectionClicked.connect(self.sort_column)
            self.grid.setHorizontalScrollMode(QW.QAbstractItemView.ScrollMode.ScrollPerPixel);self.grid.setVerticalScrollMode(QW.QAbstractItemView.ScrollMode.ScrollPerPixel)
            self.grid.selectionModel().currentChanged.connect(self.show_cell);self.grid.doubleClicked.connect(lambda index:self.full_cell(index));lay.addWidget(self.grid,1)
            copy_action=QG.QAction('Kopiuj',self.grid);copy_action.setShortcut(QG.QKeySequence('Ctrl+C'));copy_action.setShortcutContext(Qt.ShortcutContext.WidgetWithChildrenShortcut)
            copy_action.triggered.connect(lambda:self._host_window.guard(self.copy_cells));self.grid.addAction(copy_action)
