            foot=QW.QHBoxLayout();self.note=label('Dane są pobierane dopiero po otwarciu tabeli.',True);self.note.setSizePolicy(QW.QSizePolicy.Policy.Ignored,QW.QSizePolicy.Policy.Preferred);foot.addWidget(self.note,1)
            self.previous=icon_button('undo','Poprzednia strona',lambda:self.turn(-1));self.next=icon_button('redo','Następna strona',lambda:self.turn(1));foot.addWidget(self.previous);foot.addWidget(self.next)
