            return 'database_page',{'object':{k:self.obj[k] for k in ('id','name','schema','kind')},'offset':self._offset,'limit':DATABASE_PAGE_SIZE,
                'filters':self._filters,'sort':self._sort,'direction':self._direction,'primary_key':pk}
