            self.next.setEnabled(not self._busy and self._valid and bool(page.get('has_more')));self.copy_button.setEnabled(self._valid and not self._busy)
            self.filter_button.setText('Filtr · '+str(len(self._filters)) if self._filters else 'Filtr')
