                schema=self.tree_model.item(s);any_schema=False
                for k in range(schema.rowCount()):
                    group=schema.child(k);any_group=any(not self.tree.isRowHidden(i,group.index()) for i in range(group.rowCount()))
                    self.tree.setRowHidden(k,schema.index(),not any_group);any_schema|=any_group
                self.tree.setRowHidden(s,QC.QModelIndex(),not any_schema)
