            self.dense_action.toggled.connect(self.set_dense);view.addAction(self.dense_action);view.addAction(self.app_actions['reset_layout'])
            reduced=QG.QAction('Ogranicz animacje',self);reduced.setCheckable(True);reduced.setChecked(appearance_preferences(self.service.root)['reduced_motion'])
            reduced.toggled.connect(self.set_reduced_motion);view.addAction(reduced)
            self.titlebar.menu_button.setMenu(root)
