        def drive_import_dialog(self,cancel=False,second_sheet=False):
            timer=QC.QTimer(self.window);timer.setInterval(25);started=time.monotonic()
            def step():
                if time.monotonic()-started>20:
                    timer.stop();self.errors.append('Import GUI przekroczył czas testu.')
                    dialog=app.activeModalWidget()
                    if dialog:dialog.reject()
                    return
                dialog=app.activeModalWidget()
                if not isinstance(dialog,ui['ImportDialog']):return
                if cancel:timer.stop();dialog.reject();return
                if second_sheet and dialog.sheet.count()>1 and dialog.sheet.currentData()!='Drugi – dane':
                    dialog.sheet.setCurrentIndex(1);return
                if dialog.ok.isEnabled():timer.stop();dialog.validate_accept()
            timer.timeout.connect(step);timer.start();return timer
