        def test_inherited_widget_methods_are_callable(self):
            dialogs=[ui['SourceDialog'](self.window),ui['SettingsDialog'](self.window),ui['ImportDialog'](self.window)]
            try:
                widgets=[self.window,*self.window.findChildren(QW.QWidget)]
                for widget in widgets:
                    for name in ('window','layout','actions','style','palette'):
                        self.assertTrue(callable(getattr(widget,name)),f'{type(widget).__name__}.{name} is shadowed')
                    for name,value in vars(widget).items():
                        if name.startswith('_'):continue
                        for base in type(widget).__mro__:
                            if base.__module__.startswith('PySide6.') and callable(getattr(base,name,None)):
                                self.assertTrue(callable(value),f'{type(widget).__name__}.{name} shadows {base.__name__}')
                self.assertIs(self.window.titlebar.window(),self.window)
                self.assertIs(self.window.welcome.window(),self.window)
                self.assertIsInstance(dialogs[0].layout(),QW.QLayout)
                self.assertIsInstance(self.window.actions(),list)
            finally:
                for dialog in dialogs:dialog.deleteLater()
                app.processEvents()
