        def workbook_fixture(self):
            fixture=next(iter(workbook_test_suite()));fixture.root=self.root
            return fixture.make_book()
        def prepared_workbook(self,indices=(0,1)):
            path=self.workbook_fixture()
            source=workbook_stage(path,self.service.workbooks.root/('book-'+uid()))['source']
            source=workbook_prepare_bundle(source,[{'sheet_id':source['workbook']['sheets'][i]['id']} for i in indices],
                self.service.workbooks.root/('extract-'+uid()))['source']
            self.service.workbooks.publish(source,'',True);self.window.refresh_navigation();return source
        def drive_workbook_dialog(self,cancel=False):
            timer=QC.QTimer(self.window);timer.setInterval(25);state={'visited':False}
            def act():
                dialog=app.activeModalWidget()
                if isinstance(dialog,ui['WorkbookDialog']) and not dialog._job and dialog._valid==dialog._current:
                    if cancel:dialog.reject();return
                    if not state['visited']:
                        dialog.select_visible(True);dialog.sheets.setCurrentRow(1);state['visited']=True;return
                    if dialog.ok.isEnabled():dialog.validate_accept()
            timer.timeout.connect(act);timer.start();return timer
