        def contrast_cell_fixture(self,theme,style,overrides=None):
            ws=self.selection_theme(theme)
            book=ws.session.book;book['styles'].append(dict(style))
            record={'v':pack('Priorytet'),'s':len(book['styles'])-1}
            if overrides is not None:record['format']=dict(overrides)
            ws.active_sheet()['cells']['A1']=record
            ws.session.calculator.cache.clear()
            ws.select_rect((0,0,1,1));ws.grid.setFocus()
            ws.grid.viewport().update();app.processEvents()
            return ws
        def assert_cell_rendered_pair(self,grid,index,expected):
            foreground,background=expected;image=self.selection_image(grid)
            rect=grid.visualRect(index);dpr=image.devicePixelRatio()
            self.assertEqual(self.selection_pixel(image,rect.right()-10,rect.center().y()),background)
            # Inspect the actual glyph area, excluding selection outline/grid.
            colors=set()
            for y in range(max(0,int((rect.top()+4)*dpr)),min(image.height(),int((rect.bottom()-3)*dpr))):
                for x in range(max(0,int((rect.left()+6)*dpr)),min(image.width(),int((rect.right()-7)*dpr))):
                    color=image.pixelColor(x,y);colors.add((color.red(),color.green(),color.blue()))
            target=tuple(int(foreground[i:i+2],16) for i in (1,3,5))
            self.assertTrue(any(max(abs(a-b) for a,b in zip(color,target))<=8 for color in colors),
                            ('No readable glyph pixels',foreground,background))
