    class TkTests(unittest.TestCase):
        def setUp(self):
            self.temp=tempfile.TemporaryDirectory();self.root=Path(self.temp.name);self.calls=[];self.errors=[]
            self.patch=patch(__name__+'.data_root',lambda:self.root);self.patch.start()
            try:self.w=SetupWindow(root=self.root/'runtime',_test_mode=True)
            except Exception as exc:
                self.patch.stop();self.temp.cleanup()
                if isinstance(exc,ImportError) or type(exc).__name__=='TclError' and any(t in str(exc).lower() for t in ('no display',"couldn't connect to display")):
                    self.skipTest('Tk/pulpit niedostępny: '+str(exc))
                raise
            self.w.root.report_callback_exception=lambda *args:self.errors.append(str(args[1]));self.pump()
        def pump(self,condition=lambda:True,timeout=3):
            started=time.monotonic()
            while True:
                self.w.root.update();self.w.root.update_idletasks()
                if condition():break
                if time.monotonic()-started>timeout:self.fail('Czas oczekiwania Tk przekroczony.')
                time.sleep(.02)
            self.assertFalse(self.errors)
        def tearDown(self):
            if hasattr(self,'w'):
                self.w.cancel.set()
                if self.w.thread:self.w.thread.join(timeout=5)
                self.w.destroy()
            self.patch.stop();self.temp.cleanup()
